const RS=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:0});
const RS2=n=>'₹'+Number(n).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const NUM=n=>Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});
function v(id){let e=document.getElementById(id);return e?e.value:'';}
const MEDDISC='<div style="margin-top:14px;padding:11px 13px;background:#FEF6ED;border-left:3px solid #D97706;border-radius:9px;font-size:.83rem;line-height:1.6;color:#4F5D64"><b>Sehat ki chetavni:</b> ye sirf aam jaankari ke liye anuman hai, doctor ki salah nahi. Umar, bimari, dawa, garbhavastha ya athletic build se nateeja badal jaata hai. Koi bhi bada badlaav karne se pehle doctor se salah lein.</div>';
const DISC='<div class="disc">⚠️ Ye anuman hai, sirf jaankari ke liye. Not SEBI registered. Nivesh/tax faisle se pehle salahkaar se milein.</div>';

const PAGES={"love":"/love-calculator","dict":"/english-word-meaning","weather":"/mausam-weather","currency":"/currency-converter","stop":"/stopwatch-online","random":"/random-number-generator","pass":"/password-generator","goallump":"/goal-lumpsum-calculator","exammarks":"/exam-target-marks-calculator","simplify":"/fraction-simplify-calculator","numbase":"/number-system-converter","lcm":"/lcm-hcf-calculator","beunits":"/business-breakeven-calculator","pivot":"/pivot-points-calculator","optbe":"/options-breakeven-calculator","sltp":"/stop-loss-target-calculator","rr":"/risk-reward-ratio-calculator","roi":"/roi-calculator","brokerage":"/brokerage-calculator","markup":"/profit-margin-calculator","unitprice":"/price-compare-calculator","taxcompare":"/tax-regime-compare-calculator","budget":"/50-30-20-budget-calculator","tds":"/tds-calculator","revemi":"/emi-se-byaj-dar-calculator","eduloan":"/education-loan-calculator","bikeloan":"/bike-loan-emi-calculator","advtax":"/advance-tax-calculator","mssc":"/mahila-samman-calculator","pomis":"/post-office-mis-calculator","scss":"/scss-calculator","whr":"/waist-to-height-calculator","bodyfat":"/body-fat-calculator","ideal":"/ideal-weight-calculator","bmr":"/bmr-calculator","downpay":"/down-payment-calculator","vpf":"/vpf-calculator","realret":"/real-return-calculator","rentyield":"/rental-yield-calculator","sipdelay":"/sip-delay-calculator","crorepati":"/crorepati-calculator","emergency":"/emergency-fund-calculator","sipgoal":"/sip-goal-calculator","water":"/water-intake-calculator","hourly":"/salary-per-hour-calculator","sqftrate":"/property-price-calculator","dti":"/debt-to-income-calculator","saverate":"/savings-rate-calculator","nw":"/net-worth-calculator","kvp":"/kvp-calculator","nsc":"/nsc-calculator","avgdown":"/stock-averaging-calculator","cal":"/calorie-calculator","dateadd":"/date-add-subtract-calculator","sleep":"/sleep-time-calculator","pace":"/running-pace-calculator","countdown":"/din-bache-calculator","appliancebill":"/appliance-bijli-kharch-calculator","buyrent":"/ghar-kharidein-ya-kiraya-calculator","dividend":"/dividend-yield-calculator","fire":"/fire-number-calculator","rentreceipt":"/rent-receipt-calculator","typing":"/typing-speed-calculator","qr":"/qr-code-generator","case":"/case-converter","data":"/data-storage-converter","speed":"/speed-converter","readtime":"/reading-time-calculator","due":"/delivery-date-calculator","fuelcompare":"/petrol-cng-ev-compare-calculator","tile":"/tile-calculator","bill":"/bijli-bill-calculator","cgpa":"/cgpa-to-percentage-calculator","marks":"/marks-percentage-calculator","pctchange":"/percentage-change-calculator","word":"/word-counter","roman":"/roman-numerals-converter","tip":"/bill-split-calculator","fuel":"/fuel-cost-calculator","sip":"/sip-calculator","emi":"/emi-calculator","gst":"/gst-calculator","itax":"/income-tax-calculator","ppf":"/ppf-calculator","fd":"/fd-calculator","epf":"/epf-calculator","gratuity":"/gratuity-calculator","hra":"/hra-calculator","ctc":"/ctc-calculator","ci":"/compound-interest-calculator","bmi":"/bmi-calculator","age":"/age-calculator","pct":"/percentage-calculator","area":"/bigha-converter","rd":"/rd-calculator","lumpsum":"/lumpsum-calculator","stepupsip":"/step-up-sip-calculator","swp":"/swp-calculator","ssy":"/sukanya-samriddhi-calculator","nps":"/nps-calculator","cagr":"/cagr-calculator","si":"/simple-interest-calculator","retire":"/retirement-calculator","homeaff":"/home-loan-eligibility-calculator","prepay":"/loan-prepayment-calculator","ccpayoff":"/credit-card-payoff-calculator","ntw":"/number-to-words","discount":"/discount-calculator","salaryhike":"/salary-hike-calculator","unit":"/unit-converter","temp":"/temperature-converter","datediff":"/date-difference-calculator","intraday":"/intraday-calculator","possize":"/position-size-calculator","carloan":"/car-loan-emi-calculator","ploan":"/personal-loan-emi-calculator","nali":"/nali-mutthi-converter","goldloan":"/gold-loan-calculator","concrete":"/cement-sand-bajri-calculator","hectare":"/hectare-bigha-acre-converter","fasal":"/fasal-munafa-calculator","milkrate":"/doodh-rate-fat-snf-calculator","hravshl":"/old-vs-new-tax-regime-calculator","stampduty":"/stamp-duty-calculator","apy":"/apy-atal-pension-calculator","capgain":"/capital-gain-tax-calculator","rule72":"/rule-of-72-calculator","inflation":"/inflation-impact-calculator","paint":"/paint-calculator","brick":"/eent-brick-calculator","bo5":"/cbse-best-of-five-calculator","s80c":"/section-80c-calculator","deprec":"/depreciation-calculator","zakat":"/zakat-calculator","sqftsqm":"/sqft-to-sqm-converter","timedur":"/time-duration-calculator","tdee":"/tdee-calculator","macro":"/macro-calculator","sci":"/scientific-calculator","amort":"/loan-amortization-calculator","invtot":"/invoice-total-calculator","ptax":"/professional-tax-calculator","neet":"/neet-marks-calculator","recipe":"/recipe-scaler-calculator","fdladder":"/fd-ladder-calculator","attend":"/attendance-percentage-calculator","ratio":"/ratio-calculator","average":"/average-calculator","mileage":"/mileage-calculator","overtime":"/overtime-pay-calculator","leaveenc":"/leave-encashment-calculator","sgb":"/sovereign-gold-bond-calculator","pay8":"/8th-pay-commission-calculator","xirr":"/xirr-calculator"};
const tools=[
/* ===== INVESTMENT ===== */
{id:'sip',cat:'Nivesh',ic:'📈',name:'SIP Calculator',desc:'Monthly SIP ka future value',pop:1,fields:`<label class="f">Har mahine (₹)</label><input id="a" type="number" inputmode="numeric" value="5000"><div class="row2"><div><label class="f">Return % saalana</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let M=+v('a'),r=+v('r')/12/100,n=+v('y')*12,fv=r?M*((Math.pow(1+r,n)-1)/r)*(1+r):M*n,inv=M*n;return `<div class="lbl">Total value (${v('y')} saal)</div><div class="big">${RS(fv)}</div><div class="rrow"><span>Invest kiya</span><b>${RS(inv)}</b></div><div class="rrow"><span>Munafa (est.)</span><b>${RS(fv-inv)}</b></div>${DISC}`;}},
{id:'stepupsip',cat:'Nivesh',ic:'⬆️',name:'Step-Up SIP',desc:'Har saal SIP badhao',fields:`<label class="f">Shuru me har mahine (₹)</label><input id="a" type="number" inputmode="numeric" value="5000"><div class="row3"><div><label class="f">Step-up % /saal</label><input id="s" type="number" inputmode="numeric" value="10"></div><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let M=+v('a'),s=+v('s')/100,r=+v('r')/12/100,Y=+v('y'),fv=0,inv=0,cm=M;for(let yr=0;yr<Y;yr++){for(let m=0;m<12;m++){fv=(fv+cm)*(1+r);inv+=cm;}cm=cm*(1+s);}return `<div class="lbl">Total value (${Y} saal)</div><div class="big">${RS(fv)}</div><div class="rrow"><span>Invest kiya</span><b>${RS(inv)}</b></div><div class="rrow"><span>Munafa (est.)</span><b>${RS(fv-inv)}</b></div>${DISC}`;}},
{id:'lumpsum',cat:'Nivesh',ic:'💵',name:'Lumpsum Calculator',desc:'Ek baar nivesh ka growth',fields:`<label class="f">Amount (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let P=+v('a'),A=P*Math.pow(1+ +v('r')/100,+v('y'));return `<div class="lbl">Total value</div><div class="big">${RS(A)}</div><div class="rrow"><span>Munafa</span><b>${RS(A-P)}</b></div>${DISC}`;}},
{id:'swp',cat:'Nivesh',ic:'📤',name:'SWP Calculator',desc:'Har mahine nikalo, corpus kitne din',fields:`<label class="f">Corpus (₹)</label><input id="a" type="number" inputmode="numeric" value="1000000"><div class="row3"><div><label class="f">Har mahine nikalo</label><input id="w" type="number" inputmode="numeric" value="10000"></div><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="8" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let C=+v('a'),W=+v('w'),r=+v('r')/12/100,n=+v('y')*12,bal=C,i;for(i=0;i<n&&bal>0;i++){bal=bal*(1+r)-W;}return `<div class="lbl">${bal>0?'Balance '+v('y')+' saal baad':'Corpus khatam ho gaya'}</div><div class="big">${bal>0?RS(bal):'~'+Math.floor(i/12)+' saal '+(i%12)+' mahine'}</div><div class="rrow"><span>Total nikala</span><b>${RS(W*Math.min(i,n))}</b></div>${DISC}`;}},
{id:'fd',cat:'Nivesh',ic:'🏛️',name:'FD Calculator',desc:'Fixed deposit maturity',fields:`<label class="f">Amount (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="7" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="5"></div></div><label class="f">Compounding</label><select id="c"><option value="4">Quarterly</option><option value="1">Saalana</option><option value="12">Mahine</option></select>`,calc:()=>{let P=+v('a'),A=P*Math.pow(1+ +v('r')/100/+v('c'),+v('c')*+v('y'));return `<div class="lbl">Maturity</div><div class="big">${RS(A)}</div><div class="rrow"><span>Byaj</span><b>${RS(A-P)}</b></div>`;}},
{id:'rd',cat:'Nivesh',ic:'🔂',name:'RD Calculator',desc:'Recurring deposit maturity',fields:`<label class="f">Har mahine (₹)</label><input id="a" type="number" inputmode="numeric" value="5000"><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="7" step="0.1"></div><div><label class="f">Mahine</label><input id="n" type="number" inputmode="numeric" value="24"></div></div>`,calc:()=>{let M=+v('a'),i=+v('r')/12/100,n=+v('n'),A=i?M*((Math.pow(1+i,n)-1)/i)*(1+i):M*n;return `<div class="lbl">Maturity</div><div class="big">${RS(A)}</div><div class="rrow"><span>Jama</span><b>${RS(M*n)}</b></div><div class="rrow"><span>Byaj</span><b>${RS(A-M*n)}</b></div>`;}},
{id:'ppf',cat:'Nivesh',ic:'🌱',name:'PPF Calculator',desc:'15-saal PPF wealth',fields:`<label class="f">Har saal jama (₹)</label><input id="a" type="number" inputmode="numeric" value="150000"><div class="row2"><div><label class="f">Byaj % (abhi ka)</label><input id="r" type="number" inputmode="decimal" value="7.1" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="15"></div></div>`,calc:()=>{let D=+v('a'),r=+v('r')/100,Y=+v('y'),bal=0;for(let i=0;i<Y;i++){bal=(bal+D)*(1+r);}return `<div class="lbl">Maturity (${Y} saal)</div><div class="big">${RS(bal)}</div><div class="rrow"><span>Total jama</span><b>${RS(D*Y)}</b></div><div class="rrow"><span>Byaj</span><b>${RS(bal-D*Y)}</b></div><div class="hint">Byaj dar sarkar har 3 mahine me badalti — abhi ka daal.</div>`;}},
{id:'ssy',cat:'Nivesh',ic:'👧',name:'Sukanya (SSY)',desc:'Beti ke liye SSY',fields:`<label class="f">Har saal jama (₹)</label><input id="a" type="number" inputmode="numeric" value="150000"><label class="f">Byaj % (abhi ka)</label><input id="r" type="number" inputmode="decimal" value="8.2" step="0.1">`,calc:()=>{let D=+v('a'),r=+v('r')/100,bal=0;for(let i=0;i<15;i++)bal=(bal+D)*(1+r);for(let i=0;i<6;i++)bal=bal*(1+r);return `<div class="lbl">Maturity (21 saal baad)</div><div class="big">${RS(bal)}</div><div class="rrow"><span>Total jama (15 saal)</span><b>${RS(D*15)}</b></div><div class="hint">15 saal jama, 21 saal me maturity. Byaj abhi ka daal.</div>`;}},
{id:'nps',cat:'Nivesh',ic:'👴',name:'NPS Pension',desc:'Retirement corpus + pension',fields:`<label class="f">Har mahine (₹)</label><input id="a" type="number" inputmode="numeric" value="5000"><div class="row3"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="10" step="0.1"></div><div><label class="f">Abhi umar</label><input id="ag" type="number" inputmode="numeric" value="30"></div><div><label class="f">Annuity %</label><input id="an" type="number" inputmode="decimal" value="6" step="0.1"></div></div>`,calc:()=>{let M=+v('a'),r=+v('r')/12/100,n=(60-+v('ag'))*12,fv=r?M*((Math.pow(1+r,n)-1)/r)*(1+r):M*n;let annuity=fv*0.4,lump=fv*0.6,pension=annuity*(+v('an')/100)/12;return `<div class="lbl">Corpus (60 saal par)</div><div class="big">${RS(fv)}</div><div class="rrow"><span>Lumpsum (60%)</span><b>${RS(lump)}</b></div><div class="rrow"><span>Est. monthly pension</span><b>${RS(pension)}</b></div>${DISC}`;}},
{id:'gratuity',cat:'Nivesh',ic:'🎁',name:'Gratuity Calculator',desc:'Naukri chhodne pe gratuity',fields:`<label class="f">Aakhri salary — Basic+DA (₹/mahina)</label><input id="a" type="number" inputmode="numeric" value="40000"><label class="f">Naukri ke saal (5+)</label><input id="y" type="number" inputmode="numeric" value="10">`,calc:()=>{let s=+v('a'),y=+v('y');if(y<5)return '<div class="hint">Gratuity ke liye kam se kam 5 saal chahiye.</div>';let g=15*s*y/26;return `<div class="lbl">Gratuity (anuman)</div><div class="big">${RS(g)}</div><div class="hint">Formula: 15 × salary × saal ÷ 26. ₹20 lakh tak tax-free.</div>`;}},
{id:'xirr',cat:'Nivesh',ic:'\ud83d\udcc8',name:'XIRR Calculator',desc:'Alag-alag tareekh par lagaye paise ka asli saalana return',pop:1,fields:'',calc:function(){return '';}},{id:'cagr',cat:'Nivesh',ic:'📉',name:'CAGR Calculator',desc:'Saalana return rate',fields:`<div class="row2"><div><label class="f">Shuru value (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"></div><div><label class="f">Aakhri value (₹)</label><input id="b" type="number" inputmode="numeric" value="200000"></div></div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="5">`,calc:()=>{let s=+v('a'),e=+v('b'),y=+v('y'),c=(Math.pow(e/s,1/y)-1)*100;return `<div class="lbl">CAGR (saalana return)</div><div class="big">${c.toFixed(2)}%</div><div class="rrow"><span>Total growth</span><b>${((e/s-1)*100).toFixed(1)}%</b></div>`;}},
{id:'inflation',cat:'Nivesh',ic:'🔥',name:'Inflation Impact',desc:'Mehangai se paisa ki value',fields:`<label class="f">Aaj ki value (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Mehangai %</label><input id="r" type="number" inputmode="decimal" value="6" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let P=+v('a'),r=+v('r')/100,y=+v('y'),future=P*Math.pow(1+r,y),power=P/Math.pow(1+r,y);return `<div class="lbl">${y} saal baad utni cheez ka daam</div><div class="big">${RS(future)}</div><div class="rrow"><span>Aaj ke ₹${NUM(P)} ki tab value</span><b>${RS(power)}</b></div>`;}},
{id:'rule72',cat:'Nivesh',ic:'2️⃣',name:'Rule of 72',desc:'Paisa kitne saal me double',fields:`<label class="f">Byaj/return % saalana</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1">`,calc:()=>{let r=+v('r');return `<div class="lbl">Paisa double hone me</div><div class="big">${(72/r).toFixed(1)} saal</div><div class="rrow"><span>Triple (Rule 114)</span><b>${(114/r).toFixed(1)} saal</b></div>`;}},

/* ===== TRADING (edge) ===== */
{id:'intraday',cat:'Trading',ic:'⚡',name:'Intraday P&L',desc:'Buy-sell ka profit/loss',pop:1,fields:`<div class="row2"><div><label class="f">Buy price (₹)</label><input id="b" type="number" inputmode="numeric" value="100"></div><div><label class="f">Sell price (₹)</label><input id="s" type="number" inputmode="numeric" value="105"></div></div><label class="f">Quantity (shares)</label><input id="q" type="number" inputmode="numeric" value="100">`,calc:()=>{let b=+v('b'),s=+v('s'),q=+v('q');let gross=(s-b)*q;let turnover=(b+s)*q;let charges=Math.min(40,turnover*0.0003*2)+turnover*0.0001+turnover*0.0000345+gross*0.18*0;let chg=(Math.min(20,b*q*0.0003)+Math.min(20,s*q*0.0003))+(s*q*0.00025)+(turnover*0.0000345);let net=gross-chg;return `<div class="lbl">Net P&L (charges ke baad, anuman)</div><div class="big" style="color:${net>=0?'#0F766E':'#C0392B'}">${net>=0?'+':''}${RS2(net)}</div><div class="rrow"><span>Gross P&L</span><b>${RS2(gross)}</b></div><div class="rrow"><span>Charges (anuman)</span><b>~${RS2(chg)}</b></div>${DISC}`;}},
{id:'possize',cat:'Trading',ic:'🎯',name:'Position Size',desc:'Kitni qty leni (risk se)',pop:1,fields:`<label class="f">Capital (₹)</label><input id="c" type="number" inputmode="numeric" value="100000"><div class="row3"><div><label class="f">Risk %</label><input id="r" type="number" inputmode="decimal" value="1" step="0.1"></div><div><label class="f">Entry (₹)</label><input id="e" type="number" inputmode="numeric" value="100"></div><div><label class="f">Stop-loss (₹)</label><input id="s" type="number" inputmode="numeric" value="97"></div></div>`,calc:()=>{let cap=+v('c'),risk=cap*+v('r')/100,per=Math.abs(+v('e')-+v('s'));if(per<=0)return '<div class="hint">Entry aur SL alag hone chahiye.</div>';let qty=Math.floor(risk/per);return `<div class="lbl">Quantity leni chahiye</div><div class="big">${qty} shares</div><div class="rrow"><span>Max risk</span><b>${RS(risk)}</b></div><div class="rrow"><span>Per share risk</span><b>${RS2(per)}</b></div>${DISC}`;}},
{id:'rr',cat:'Trading',ic:'⚖️',name:'Risk-Reward Ratio',desc:'Trade ka R:R',fields:`<div class="row3"><div><label class="f">Entry (₹)</label><input id="e" type="number" inputmode="numeric" value="100"></div><div><label class="f">Target (₹)</label><input id="t" type="number" inputmode="numeric" value="110"></div><div><label class="f">Stop-loss (₹)</label><input id="s" type="number" inputmode="numeric" value="97"></div></div>`,calc:()=>{let e=+v('e'),t=+v('t'),s=+v('s');let reward=Math.abs(t-e),risk=Math.abs(e-s);if(risk<=0)return '<div class="hint">SL entry se alag ho.</div>';let rr=reward/risk;return `<div class="lbl">Risk : Reward</div><div class="big">1 : ${rr.toFixed(2)}</div><div class="rrow"><span>Reward</span><b>${RS2(reward)}/share</b></div><div class="rrow"><span>Risk</span><b>${RS2(risk)}/share</b></div><div class="hint">1:2 ya usse behtar aam taur pe achha maana jaata.</div>${DISC}`;}},
{id:'optbe',cat:'Trading',ic:'🎫',name:'Options Break-even',desc:'CE/PE break-even price',fields:`<div class="row2"><div><label class="f">Strike (₹)</label><input id="k" type="number" inputmode="numeric" value="24000"></div><div><label class="f">Premium (₹)</label><input id="p" type="number" inputmode="numeric" value="120"></div></div><label class="f">Type</label><select id="t"><option value="ce">Call (CE)</option><option value="pe">Put (PE)</option></select>`,calc:()=>{let k=+v('k'),p=+v('p'),be=v('t')==='ce'?k+p:k-p;return `<div class="lbl">Break-even (spot yahan pahunche to 0)</div><div class="big">${NUM(be)}</div><div class="rrow"><span>Iske ${v('t')==='ce'?'upar':'neeche'} profit shuru</span><b>${NUM(be)}</b></div>${DISC}`;}},
{id:'avgdown',cat:'Trading',ic:'📊',name:'Stock Averaging',desc:'Average buy price nikalo',fields:`<div class="row2"><div><label class="f">Qty 1</label><input id="q1" type="number" inputmode="numeric" value="100"></div><div><label class="f">Price 1 (₹)</label><input id="p1" type="number" inputmode="numeric" value="120"></div></div><div class="row2"><div><label class="f">Qty 2</label><input id="q2" type="number" inputmode="numeric" value="100"></div><div><label class="f">Price 2 (₹)</label><input id="p2" type="number" inputmode="numeric" value="100"></div></div>`,calc:()=>{let q1=+v('q1'),p1=+v('p1'),q2=+v('q2'),p2=+v('p2');let avg=(q1*p1+q2*p2)/(q1+q2);return `<div class="lbl">Naya average price</div><div class="big">${RS2(avg)}</div><div class="rrow"><span>Total qty</span><b>${q1+q2}</b></div><div class="rrow"><span>Total invest</span><b>${RS(q1*p1+q2*p2)}</b></div>`;}},

/* ===== LOAN / TAX ===== */
{id:'emi',cat:'Loan/Tax',ic:'🏦',name:'EMI Calculator',desc:'Loan ki monthly kisht',pop:1,fields:`<label class="f">Loan amount (₹)</label><input id="a" type="number" inputmode="numeric" value="500000"><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="9" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="5"></div></div>`,calc:()=>{let P=+v('a'),R=+v('r')/12/100,N=+v('y')*12,e=R?P*R*Math.pow(1+R,N)/(Math.pow(1+R,N)-1):P/N,t=e*N;return `<div class="lbl">Monthly EMI</div><div class="big">${RS(e)}</div><div class="rrow"><span>Total byaj</span><b>${RS(t-P)}</b></div><div class="rrow"><span>Total bhugtan</span><b>${RS(t)}</b></div>`;}},
{id:'gst',cat:'Loan/Tax',ic:'🧾',name:'GST Calculator',desc:'GST jodo ya hatao',pop:1,fields:`<label class="f">Amount (₹)</label><input id="a" type="number" inputmode="numeric" value="1000"><div class="row2"><div><label class="f">GST %</label><select id="r"><option>5</option><option>12</option><option selected>18</option><option>28</option></select></div><div><label class="f">Type</label><select id="t"><option value="add">Jodo</option><option value="rem">Hatao</option></select></div></div>`,calc:()=>{let a=+v('a'),r=+v('r')/100,t=v('t'),base,gst,tot;if(t==='add'){base=a;gst=a*r;tot=a+gst;}else{base=a/(1+r);gst=a-base;tot=a;}return `<div class="lbl">${t==='add'?'GST ke saath':'GST ke bina'}</div><div class="big">${RS2(t==='add'?tot:base)}</div><div class="rrow"><span>Base</span><b>${RS2(base)}</b></div><div class="rrow"><span>GST (${v('r')}%)</span><b>${RS2(gst)}</b></div>`;}},
{id:'hra',cat:'Loan/Tax',ic:'🏠',name:'HRA Exemption',desc:'HRA tax chhut',fields:`<label class="f">Basic salary /saal (₹)</label><input id="b" type="number" inputmode="numeric" value="360000"><label class="f">HRA mila /saal (₹)</label><input id="h" type="number" inputmode="numeric" value="180000"><label class="f">Rent diya /saal (₹)</label><input id="r" type="number" inputmode="numeric" value="180000"><label class="f">Metro city?</label><select id="m"><option value="0.5">Haan (50%)</option><option value="0.4">Nahi (40%)</option></select>`,calc:()=>{let b=+v('b'),h=+v('h'),r=+v('r'),m=+v('m');let e=Math.max(0,Math.min(h,r-0.1*b,m*b));return `<div class="lbl">HRA tax-free (anuman)</div><div class="big">${RS(e)}</div><div class="hint">Teeno me se sabse kam: HRA mila, rent-10% basic, aur ${m==0.5?'50':'40'}% basic.</div>${DISC}`;}},
{id:'pay8',cat:'Loan/Tax',ic:'\ud83c\udfdb\ufe0f',name:'8th Pay Commission',desc:'Fitment factor daalkar nayi salary aur arrear ka anumaan',pop:1,fields:'',calc:function(){return '';}},{id:'ctc',cat:'Loan/Tax',ic:'💼',name:'CTC to In-Hand',desc:'CTC se rough in-hand',fields:`<label class="f">CTC /saal (₹)</label><input id="a" type="number" inputmode="numeric" value="600000">`,calc:()=>{let c=+v('a');let monthly=c/12;let inhand=c*0.88/12;return `<div class="lbl">Rough monthly in-hand</div><div class="big">${RS(inhand)}</div><div class="rrow"><span>Monthly gross</span><b>${RS(monthly)}</b></div><div class="hint">Bahut rough anuman (~12% PF/tax kata). Asli in-hand company structure + tax par depend karta.</div>${DISC}`;}},

/* ===== ROZANA ===== */
{id:'ntw',cat:'Rozana',ic:'🔢',name:'Number to Words (₹)',desc:'Rupaye shabdon me (cheque)',pop:1,fields:`<label class="f">Amount (₹)</label><input id="a" type="number" inputmode="numeric" value="125000" oninput="doNTW()"><div id="ntwout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'pct',cat:'Rozana',ic:'％',name:'Percentage',desc:'X ka Y%',fields:`<label class="f">Number</label><input id="a" type="number" inputmode="numeric" value="500"><label class="f">Percent %</label><input id="p" type="number" inputmode="numeric" value="15">`,calc:()=>{let a=+v('a'),p=+v('p');return `<div class="lbl">${a} ka ${p}%</div><div class="big">${NUM(a*p/100)}</div>`;}},
{id:'age',cat:'Rozana',ic:'🎂',name:'Age Calculator',desc:'Umar theek-theek',pop:1,fields:`<label class="f">Janm tareekh</label><input id="d" type="date">`,calc:()=>{if(!v('d'))return '<div class="hint">Tareekh chuniye.</div>';let b=new Date(v('d')),n=new Date(),y=n.getFullYear()-b.getFullYear(),m=n.getMonth()-b.getMonth(),d=n.getDate()-b.getDate();if(d<0){m--;d+=new Date(n.getFullYear(),n.getMonth(),0).getDate();}if(m<0){y--;m+=12;}let days=Math.floor((n-b)/864e5);return `<div class="lbl">Umar</div><div class="big">${y} saal</div><div class="rrow"><span>Aur</span><b>${m} mahine ${d} din</b></div><div class="rrow"><span>Total din</span><b>${days.toLocaleString('en-IN')}</b></div>`;}},
{id:'datediff',cat:'Rozana',ic:'📅',name:'Date Difference',desc:'Do tareekh ka farak',fields:`<label class="f">Pehli</label><input id="d1" type="date"><label class="f">Doosri</label><input id="d2" type="date">`,calc:()=>{if(!v('d1')||!v('d2'))return '<div class="hint">Dono tareekh chuniye.</div>';let days=Math.abs(Math.round((new Date(v('d2'))-new Date(v('d1')))/864e5));return `<div class="lbl">Farak</div><div class="big">${days.toLocaleString('en-IN')} din</div><div class="rrow"><span>Hafte</span><b>${Math.floor(days/7)} hafte ${days%7} din</b></div>`;}},
{id:'countdown',cat:'Rozana',ic:'⏳',name:'Din Bache',desc:'Tareekh tak kitne din',fields:`<label class="f">Aane wali tareekh</label><input id="d" type="date">`,calc:()=>{if(!v('d'))return '<div class="hint">Tareekh chuniye.</div>';let diff=Math.ceil((new Date(v('d'))-new Date())/864e5);return `<div class="lbl">${diff>=0?'Bache din':'Beet chuke din'}</div><div class="big">${Math.abs(diff)} din</div>`;}},
{id:'fuel',cat:'Rozana',ic:'⛽',name:'Fuel Cost',desc:'Safar ka petrol kharcha',fields:`<div class="row2"><div><label class="f">Doori (km)</label><input id="d" type="number" inputmode="numeric" value="100"></div><div><label class="f">Mileage (km/L)</label><input id="m" type="number" inputmode="numeric" value="15"></div></div><label class="f">Bhaav (₹/L)</label><input id="p" type="number" inputmode="numeric" value="100">`,calc:()=>{let l=+v('d')/+v('m');return `<div class="lbl">Kharcha</div><div class="big">${RS(l*+v('p'))}</div><div class="rrow"><span>Fuel chahiye</span><b>${l.toFixed(2)} litre</b></div>`;}},
{id:'tip',cat:'Rozana',ic:'🍽️',name:'Bill Split',desc:'Bill baanto + tip',fields:`<label class="f">Bill (₹)</label><input id="a" type="number" inputmode="numeric" value="1200"><div class="row2"><div><label class="f">Tip %</label><input id="t" type="number" inputmode="numeric" value="10"></div><div><label class="f">Log</label><input id="n" type="number" inputmode="numeric" value="4"></div></div>`,calc:()=>{let a=+v('a'),t=a*+v('t')/100,n=+v('n')||1,tot=a+t;return `<div class="lbl">Per person</div><div class="big">${RS2(tot/n)}</div><div class="rrow"><span>Tip</span><b>${RS2(t)}</b></div><div class="rrow"><span>Total</span><b>${RS2(tot)}</b></div>`;}},
{id:'bill',cat:'Rozana',ic:'💡',name:'Bijli Bill',desc:'Electricity bill anuman',fields:`<label class="f">Units (kWh)</label><input id="u" type="number" inputmode="numeric" value="200"><label class="f">Rate (₹/unit)</label><input id="r" type="number" inputmode="decimal" value="7" step="0.1"><label class="f">Fixed charge (₹)</label><input id="f" type="number" inputmode="numeric" value="100">`,calc:()=>{let e=+v('u')*+v('r');return `<div class="lbl">Anumanit bill</div><div class="big">${RS(e+ +v('f'))}</div><div class="rrow"><span>Energy</span><b>${RS(e)}</b></div>`;}},

/* ===== CONVERTER ===== */
{id:'area',cat:'Converter',ic:'🗺️',name:'Area (Bigha)',desc:'Sqft, gaj, acre, bigha',pop:1,fields:`<div class="row2"><div><label class="f">Value</label><input id="val" type="number" inputmode="numeric" value="1" oninput="doArea()"></div><div><label class="f">From</label><select id="from" onchange="doArea()"></select></div></div><label class="f">To</label><select id="to" onchange="doArea()"></select><div id="areaout" class="result show" style="margin-top:14px"></div><div class="hint">Bigha har rajya me alag — yahan ~27000 sqft. Apne ilaake ka confirm karein.</div>`,custom:true},
{id:'unit',cat:'Converter',ic:'📐',name:'Length / Weight',desc:'Meter, kg, mile, lb',fields:`<label class="f">Type</label><select id="t" onchange="renderUnit()"><option value="len">Length</option><option value="wt">Weight</option></select><div class="row2"><div><label class="f">Value</label><input id="val" type="number" inputmode="numeric" value="1" oninput="doUnit()"></div><div><label class="f">From</label><select id="from" onchange="doUnit()"></select></div></div><label class="f">To</label><select id="to" onchange="doUnit()"></select><div id="uout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'temp',cat:'Converter',ic:'🌡️',name:'Temperature',desc:'C, F, K',fields:`<div class="row2"><div><label class="f">Value</label><input id="val" type="number" inputmode="numeric" value="37" oninput="doTemp()"></div><div><label class="f">From</label><select id="from" onchange="doTemp()"><option>C</option><option>F</option><option>K</option></select></div></div><label class="f">To</label><select id="to" onchange="doTemp()"><option>F</option><option>C</option><option>K</option></select><div id="tout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'speed',cat:'Converter',ic:'🚗',name:'Speed',desc:'kmph, mph, m/s',fields:`<div class="row2"><div><label class="f">Value</label><input id="val" type="number" inputmode="numeric" value="60" oninput="doSpeed()"></div><div><label class="f">From</label><select id="from" onchange="doSpeed()"><option>kmph</option><option>mph</option><option>m/s</option></select></div></div><label class="f">To</label><select id="to" onchange="doSpeed()"><option>mph</option><option>kmph</option><option>m/s</option></select><div id="spout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'data',cat:'Converter',ic:'💾',name:'Data Storage',desc:'KB, MB, GB, TB',fields:`<div class="row2"><div><label class="f">Value</label><input id="val" type="number" inputmode="numeric" value="1" oninput="doData()"></div><div><label class="f">From</label><select id="from" onchange="doData()"><option>GB</option><option>KB</option><option>MB</option><option>TB</option></select></div></div><label class="f">To</label><select id="to" onchange="doData()"><option>MB</option><option>KB</option><option>GB</option><option>TB</option></select><div id="dout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'roman',cat:'Converter',ic:'Ⅻ',name:'Roman Numerals',desc:'Number → Roman',fields:`<label class="f">Number (1-3999)</label><input id="a" type="number" inputmode="numeric" value="2026" oninput="doRoman()"><div id="romout" class="result show" style="margin-top:14px"></div>`,custom:true},

/* ===== SEHAT ===== */
{id:'bmi',cat:'Sehat',ic:'⚖️',name:'BMI Calculator',desc:'Sehat index',pop:1,fields:`<div class="row2"><div><label class="f">Weight (kg)</label><input id="w" type="number" inputmode="numeric" value="70"></div><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div></div>`,calc:()=>{let w=+v('w'),h=+v('h')/100,b=w/(h*h),s=b<18.5?'Kam':b<25?'Sahi (normal)':b<30?'Zyada':'Bahut zyada';return `<div class="lbl">BMI</div><div class="big">${b.toFixed(1)}</div><div class="rrow"><span>Sthiti</span><b>${s}</b></div>`+MEDDISC;}},
{id:'cal',cat:'Sehat',ic:'🔥',name:'Calorie (BMR)',desc:'Roz ki calorie',fields:`<div class="row2"><div><label class="f">Umar</label><input id="age" type="number" inputmode="numeric" value="30"></div><div><label class="f">Ling</label><select id="g"><option value="m">Purush</option><option value="f">Mahila</option></select></div></div><div class="row2"><div><label class="f">Weight (kg)</label><input id="w" type="number" inputmode="numeric" value="70"></div><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div></div><label class="f">Activity</label><select id="act"><option value="1.2">Kam</option><option value="1.375">Halka</option><option value="1.55" selected>Madhyam</option><option value="1.725">Zyada</option></select>`,calc:()=>{let a=+v('age'),w=+v('w'),h=+v('h'),bmr=v('g')==='m'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161,td=bmr*+v('act');return `<div class="lbl">Roz ki calorie</div><div class="big">${Math.round(td)} kcal</div><div class="rrow"><span>BMR (aaram)</span><b>${Math.round(bmr)} kcal</b></div><div class="hint">Anuman. Diet ke liye expert se milein.</div>`+MEDDISC;}},
{id:'due',cat:'Sehat',ic:'🤰',name:'Delivery Date',desc:'Pregnancy due date',fields:`<label class="f">Aakhri period (LMP)</label><input id="d" type="date">`,calc:()=>{if(!v('d'))return '<div class="hint">Tareekh chuniye.</div>';let d=new Date(v('d'));d.setDate(d.getDate()+280);return `<div class="lbl">Anumanit delivery date</div><div class="big" style="font-size:1.5rem">${d.toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric'})}</div><div class="hint">Anuman. Doctor se milein.</div>`+MEDDISC;}},

/* ===== UTILITY ===== */
{id:'word',cat:'Utility',ic:'🔤',name:'Word Counter',desc:'Shabd aur akshar',fields:`<label class="f">Text</label><textarea id="t" oninput="wc()" style="min-height:120px"></textarea><div id="wout" class="result show" style="margin-top:14px"></div>`,custom:true},
{id:'case',cat:'Utility',ic:'🔠',name:'Case Converter',desc:'UPPER, lower, Title',fields:`<label class="f">Text</label><textarea id="t" style="min-height:90px"></textarea><div class="row2" style="margin-top:10px"><button class="btn" style="margin:0" onclick="doCase('up')">UPPER</button><button class="btn sec" style="margin:0" onclick="doCase('low')">lower</button></div><div class="row2" style="margin-top:8px"><button class="btn sec" style="margin:0" onclick="doCase('title')">Title</button><button class="btn" style="margin:0" onclick="doCase('sent')">Sentence</button></div><div id="caseout" class="result" style="margin-top:14px"></div>`,custom:true},
{id:'pass',cat:'Utility',ic:'🔐',name:'Password Generator',desc:'Strong password',pop:1,fields:`<label class="f">Lambai: <b id="pl">14</b></label><input id="len" type="range" min="6" max="32" value="14" oninput="document.getElementById('pl').textContent=this.value"><button class="btn" onclick="genPass()">Password banao</button><div id="pout" class="result"></div>`,custom:true},
{id:'qr',cat:'Utility',ic:'📱',name:'QR Code',desc:'Link/text ka QR',pop:1,fields:`<label class="f">Text ya link</label><input id="t" type="text" value="https://" oninput="genQR()"><div id="qrout"></div><div class="hint">QR par long-press karke save karein.</div>`,custom:true},
{id:'random',cat:'Utility',ic:'🎲',name:'Random / Dice',desc:'Random number, dice',fields:`<div class="row2"><div><label class="f">Min</label><input id="mn" type="number" inputmode="numeric" value="1"></div><div><label class="f">Max</label><input id="mx" type="number" inputmode="numeric" value="100"></div></div><button class="btn" onclick="doRandom()">Random</button><div class="row2" style="margin-top:8px"><button class="btn sec" style="margin:0" onclick="doDice()">🎲 Dice</button><button class="btn sec" style="margin:0" onclick="doCoin()">🪙 Sikka</button></div><div id="rout" class="result"></div>`,custom:true},
{id:'stop',cat:'Utility',ic:'⏱️',name:'Stopwatch',desc:'Samay gino',fields:`<div id="swd" style="font-family:'Bricolage Grotesque';font-size:3rem;font-weight:800;text-align:center;color:var(--brand);margin:14px 0">00:00.0</div><div class="row3"><button class="btn" style="margin:0" onclick="swStart()">Start</button><button class="btn sec" style="margin:0" onclick="swStop()">Stop</button><button class="btn sec" style="margin:0" onclick="swReset()">Reset</button></div>`,custom:true},
/* ===== BATCH 2 — 15 naye tools ===== */
{id:'si',cat:'Nivesh',ic:'📎',name:'Simple Interest',desc:'Seedha byaj',fields:`<label class="f">Principal (₹)</label><input id="p" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Rate % /saal</label><input id="r" type="number" inputmode="decimal" value="8" step="0.1"></div><div><label class="f">Saal</label><input id="t" type="number" inputmode="numeric" value="5"></div></div>`,calc:()=>{let p=+v('p'),si=p*+v('r')*+v('t')/100;return `<div class="lbl">Simple interest</div><div class="big">${RS(si)}</div><div class="rrow"><span>Total (P+I)</span><b>${RS(p+si)}</b></div>`;}},
{id:'ci',cat:'Nivesh',ic:'🔁',name:'Compound Interest',desc:'Chakravriddhi byaj',fields:`<label class="f">Principal (₹)</label><input id="p" type="number" inputmode="numeric" value="100000"><div class="row3"><div><label class="f">Rate %</label><input id="r" type="number" inputmode="decimal" value="8" step="0.1"></div><div><label class="f">Saal</label><input id="t" type="number" inputmode="numeric" value="5"></div><div><label class="f">Compounding</label><select id="n"><option value="1">Saal</option><option value="4">Quarter</option><option value="12">Mahina</option></select></div></div>`,calc:()=>{let p=+v('p'),n=+v('n'),A=p*Math.pow(1+ +v('r')/100/n,n*+v('t'));return `<div class="lbl">Total value</div><div class="big">${RS(A)}</div><div class="rrow"><span>Byaj</span><b>${RS(A-p)}</b></div>`;}},
{id:'sipgoal',cat:'Nivesh',ic:'🎯',name:'SIP Goal (target)',desc:'Target ke liye monthly SIP',fields:`<label class="f">Target amount (₹)</label><input id="fv" type="number" inputmode="numeric" value="1000000"><div class="row2"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let fv=+v('fv'),r=+v('r')/12/100,n=+v('y')*12,M=r?fv*r/((Math.pow(1+r,n)-1)*(1+r)):fv/n;return `<div class="lbl">Har mahine SIP chahiye</div><div class="big">${RS(M)}</div><div class="rrow"><span>Total invest</span><b>${RS(M*n)}</b></div>${DISC}`;}},
{id:'retire',cat:'Nivesh',ic:'🏖️',name:'Retirement Corpus',desc:'Retire ke liye kitna fund',fields:`<label class="f">Abhi ka monthly kharcha (₹)</label><input id="e" type="number" inputmode="numeric" value="30000"><div class="row3"><div><label class="f">Abhi umar</label><input id="a" type="number" inputmode="numeric" value="30"></div><div><label class="f">Retire umar</label><input id="ra" type="number" inputmode="numeric" value="60"></div><div><label class="f">Mehangai %</label><input id="i" type="number" inputmode="decimal" value="6" step="0.1"></div></div>`,calc:()=>{let e=+v('e'),yrs=+v('ra')-+v('a'),fe=e*Math.pow(1+ +v('i')/100,yrs),corpus=fe*12*25;return `<div class="lbl">Retire pe chahiye (anuman)</div><div class="big">${RS(corpus)}</div><div class="rrow"><span>Tab ka monthly kharcha</span><b>${RS(fe)}</b></div><div class="hint">Rough (25x saalana kharcha, 4% rule). Sirf andaaza.</div>${DISC}`;}},
{id:'discount',cat:'Rozana',ic:'🏷️',name:'Discount Calculator',desc:'Sale ke baad daam',fields:`<div class="row2"><div><label class="f">Price (₹)</label><input id="p" type="number" inputmode="numeric" value="2000"></div><div><label class="f">Discount %</label><input id="d" type="number" inputmode="numeric" value="25"></div></div>`,calc:()=>{let p=+v('p'),d=+v('d'),f=p*(1-d/100);return `<div class="lbl">Final price</div><div class="big">${RS2(f)}</div><div class="rrow"><span>Bacha</span><b>${RS2(p-f)}</b></div>`;}},
{id:'pctchange',cat:'Rozana',ic:'📊',name:'% Change',desc:'2 number ke beech % farak',fields:`<div class="row2"><div><label class="f">Purana</label><input id="a" type="number" inputmode="numeric" value="100"></div><div><label class="f">Naya</label><input id="b" type="number" inputmode="numeric" value="125"></div></div>`,calc:()=>{let a=+v('a'),b=+v('b');if(!a)return '<div class="hint">Purana 0 nahi ho sakta.</div>';let c=(b-a)/a*100;return `<div class="lbl">${c>=0?'Badha':'Ghata'}</div><div class="big">${c>=0?'+':''}${c.toFixed(2)}%</div>`;}},
{id:'ccpayoff',cat:'Loan/Tax',ic:'💳',name:'Credit Card Payoff',desc:'Kitne mahine me chukega',fields:`<label class="f">Outstanding (₹)</label><input id="b" type="number" inputmode="numeric" value="50000"><div class="row2"><div><label class="f">Byaj % /saal</label><input id="r" type="number" inputmode="decimal" value="36" step="0.1"></div><div><label class="f">Har mahine (₹)</label><input id="p" type="number" inputmode="numeric" value="5000"></div></div>`,calc:()=>{let bal=+v('b'),i=+v('r')/12/100,pay=+v('p');if(pay<=bal*i)return `<div class="lbl">Warning</div><div class="big" style="font-size:1.2rem;color:#C0392B">Payment kam hai!</div><div class="hint">Itne me sirf byaj bhi nahi katega. Zyada bharo.</div>`;let n=Math.ceil(-Math.log(1-bal*i/pay)/Math.log(1+i));return `<div class="lbl">Chukne me</div><div class="big">${n} mahine</div><div class="rrow"><span>Total bharoge</span><b>${RS(pay*n)}</b></div><div class="rrow"><span>Byaj (extra)</span><b>${RS(pay*n-bal)}</b></div>`;}},
{id:'salaryhike',cat:'Loan/Tax',ic:'📈',name:'Salary Hike %',desc:'Increment percentage',fields:`<div class="row2"><div><label class="f">Purani salary (₹)</label><input id="a" type="number" inputmode="numeric" value="50000"></div><div><label class="f">Nayi salary (₹)</label><input id="b" type="number" inputmode="numeric" value="60000"></div></div>`,calc:()=>{let a=+v('a'),b=+v('b');if(!a)return '<div class="hint">Purani 0 nahi.</div>';return `<div class="lbl">Hike</div><div class="big">${((b-a)/a*100).toFixed(2)}%</div><div class="rrow"><span>Badhotri</span><b>${RS(b-a)}</b></div>`;}},
{id:'sqftrate',cat:'Loan/Tax',ic:'🏘️',name:'Property Price',desc:'Area × rate = daam',fields:`<div class="row2"><div><label class="f">Area (sq ft)</label><input id="a" type="number" inputmode="numeric" value="1000"></div><div><label class="f">Rate (₹/sq ft)</label><input id="r" type="number" inputmode="numeric" value="5000"></div></div>`,calc:()=>{let t=+v('a')*+v('r');return `<div class="lbl">Total property price</div><div class="big">${RS(t)}</div>`;}},
{id:'water',cat:'Sehat',ic:'💧',name:'Water Intake',desc:'Roz kitna paani',fields:`<label class="f">Weight (kg)</label><input id="w" type="number" inputmode="numeric" value="70">`,calc:()=>{let l=+v('w')*0.033;return `<div class="lbl">Roz paani (anuman)</div><div class="big">${l.toFixed(1)} litre</div><div class="hint">~8-10 glass. Garmi/exercise me zyada.</div>`+MEDDISC;}},
{id:'ideal',cat:'Sehat',ic:'🧍',name:'Ideal Weight',desc:'Height se sahi wazan',fields:`<div class="row2"><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div><div><label class="f">Ling</label><select id="g"><option value="m">Purush</option><option value="f">Mahila</option></select></div></div>`,calc:()=>{let inch=+v('h')/2.54,over=Math.max(0,inch-60),base=v('g')==='m'?50:45.5,w=base+2.3*over;return `<div class="lbl">Aadarsh wazan (Devine)</div><div class="big">${w.toFixed(1)} kg</div><div class="hint">Anuman. Body type se farak padta.</div>`+MEDDISC;}},
{id:'bodyfat',cat:'Sehat',ic:'📉',name:'Body Fat %',desc:'US Navy method',fields:`<label class="f">Ling</label><select id="g" onchange="document.getElementById('hipw').style.display=this.value==='f'?'block':'none'"><option value="m">Purush</option><option value="f">Mahila</option></select><div class="row2"><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div><div><label class="f">Neck (cm)</label><input id="n" type="number" inputmode="numeric" value="38"></div></div><label class="f">Waist (cm)</label><input id="wa" type="number" inputmode="numeric" value="85"><div id="hipw" style="display:none"><label class="f">Hip (cm)</label><input id="hip" type="number" inputmode="numeric" value="95"></div>`,calc:()=>{let h=+v('h'),n=+v('n'),wa=+v('wa'),bf;if(v('g')==='m'){bf=495/(1.0324-0.19077*Math.log10(wa-n)+0.15456*Math.log10(h))-450;}else{let hip=+v('hip');bf=495/(1.29579-0.35004*Math.log10(wa+hip-n)+0.22100*Math.log10(h))-450;}if(!isFinite(bf)||bf<0)return '<div class="hint">Values check karein.</div>';return `<div class="lbl">Body fat (anuman)</div><div class="big">${bf.toFixed(1)}%</div><div class="hint">US Navy formula, aam andaaza.</div>`+MEDDISC;}},
{id:'pace',cat:'Sehat',ic:'🏃',name:'Running Pace',desc:'Daudne ki speed',fields:`<div class="row2"><div><label class="f">Doori (km)</label><input id="d" type="number" inputmode="numeric" value="5"></div><div><label class="f">Samay (min)</label><input id="t" type="number" inputmode="numeric" value="30"></div></div>`,calc:()=>{let d=+v('d'),t=+v('t');if(!d)return '<div class="hint">Doori daalein.</div>';let pk=t/d,pm=t/(d/1.60934);return `<div class="lbl">Pace</div><div class="big">${Math.floor(pk)}:${String(Math.round((pk%1)*60)).padStart(2,'0')} /km</div><div class="rrow"><span>Per mile</span><b>${Math.floor(pm)}:${String(Math.round((pm%1)*60)).padStart(2,'0')} /mile</b></div><div class="rrow"><span>Speed</span><b>${(d/(t/60)).toFixed(1)} km/h</b></div>`+MEDDISC;}},
{id:'pivot',cat:'Trading',ic:'📐',name:'Pivot Points',desc:'Support/resistance levels',fields:`<div class="row3"><div><label class="f">High</label><input id="h" type="number" inputmode="numeric" value="24100"></div><div><label class="f">Low</label><input id="l" type="number" inputmode="numeric" value="23900"></div><div><label class="f">Close</label><input id="c" type="number" inputmode="numeric" value="24000"></div></div>`,calc:()=>{let H=+v('h'),L=+v('l'),C=+v('c'),P=(H+L+C)/3,R1=2*P-L,S1=2*P-H,R2=P+(H-L),S2=P-(H-L),R3=H+2*(P-L),S3=L-2*(H-P);return `<div class="lbl">Pivot (P)</div><div class="big">${NUM(+P.toFixed(2))}</div><div class="rrow"><span>R1 / S1</span><b>${NUM(+R1.toFixed(1))} / ${NUM(+S1.toFixed(1))}</b></div><div class="rrow"><span>R2 / S2</span><b>${NUM(+R2.toFixed(1))} / ${NUM(+S2.toFixed(1))}</b></div><div class="rrow"><span>R3 / S3</span><b>${NUM(+R3.toFixed(1))} / ${NUM(+S3.toFixed(1))}</b></div>${DISC}`;}},
{id:'readtime',cat:'Utility',ic:'📖',name:'Reading Time',desc:'Padhne/bolne ka samay',fields:`<label class="f">Text paste karo</label><textarea id="t" oninput="doRead()" style="min-height:110px"></textarea><div id="rdout" class="result show" style="margin-top:14px"></div>`,custom:true},
/* ===== STAGE 1 — LIVE (free API) ===== */
{id:'weather',cat:'Live',ic:'🌦️',name:'Weather',desc:'Aaj + kal ka mausam',fields:`<label class="f">Sheher ka naam</label><input id="city" type="text" value="Bageshwar" onkeydown="if(event.key==='Enter')doWeather()"><button class="btn" onclick="doWeather()">Mausam dekho</button><div id="wxout" class="result"></div>`,custom:true},
{id:'currency',cat:'Live',ic:'💱',name:'Currency Converter',desc:'Live exchange rate',fields:`<label class="f">Rakam</label><input id="amt" type="number" inputmode="numeric" value="100"><div class="row2"><div><label class="f">Se (from)</label><select id="from"></select></div><div><label class="f">Ko (to)</label><select id="to"></select></div></div><button class="btn" onclick="doCurrency()">Convert</button><div id="cxout" class="result"></div>`,custom:true},
{id:'dict',cat:'Live',ic:'📖',name:'Word Meaning',desc:'English word dictionary',fields:`<label class="f">Word (English)</label><input id="word" type="text" value="calculate" onkeydown="if(event.key==='Enter')doDict()"><button class="btn" onclick="doDict()">Meaning dekho</button><div id="dxout" class="result"></div>`,custom:true},
/* ===== BATCH 3 — 6 naye safe tools ===== */
{id:'epf',cat:'Nivesh',ic:'🏢',name:'EPF Calculator',desc:'PF corpus anuman',fields:`<label class="f">Har mahine total contribution (₹)</label><input id="m" type="number" inputmode="numeric" value="3600"><div class="row2"><div><label class="f">Byaj %/saal</label><input id="r" type="number" inputmode="decimal" value="8.15" step="0.01"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="20"></div></div>`,calc:()=>{let M=+v('m'),r=+v('r')/12/100,n=+v('y')*12,fv=r?M*((Math.pow(1+r,n)-1)/r):M*n;return `<div class="lbl">EPF corpus (anuman)</div><div class="big">${RS(fv)}</div><div class="rrow"><span>Total jama</span><b>${RS(M*n)}</b></div><div class="rrow"><span>Byaj</span><b>${RS(fv-M*n)}</b></div><div class="hint">Contribution/byaj badalne pe farak. Anuman.</div>${DISC}`;}},
{id:'nsc',cat:'Nivesh',ic:'📜',name:'NSC Calculator',desc:'5-saal maturity',fields:`<label class="f">Jama rakam (₹)</label><input id="p" type="number" inputmode="numeric" value="100000"><label class="f">Byaj %/saal</label><input id="r" type="number" inputmode="decimal" value="7.7" step="0.01">`,calc:()=>{let p=+v('p'),A=p*Math.pow(1+ +v('r')/100,5);return `<div class="lbl">5 saal baad maturity</div><div class="big">${RS(A)}</div><div class="rrow"><span>Byaj</span><b>${RS(A-p)}</b></div><div class="hint">NSC 5 saal lock, yearly compound.</div>`;}},
{id:'dividend',cat:'Trading',ic:'💸',name:'Dividend Yield',desc:'Yield % nikaalo',fields:`<div class="row2"><div><label class="f">Saalana dividend/share (₹)</label><input id="d" type="number" inputmode="numeric" value="12"></div><div><label class="f">Share price (₹)</label><input id="p" type="number" inputmode="numeric" value="400"></div></div>`,calc:()=>{let p=+v('p');if(!p)return '<div class="hint">Price daalein.</div>';return `<div class="lbl">Dividend yield</div><div class="big">${(+v('d')/p*100).toFixed(2)}%</div>`;}},
{id:'markup',cat:'Loan/Tax',ic:'🏷️',name:'Profit / Margin',desc:'Cost se profit%',fields:`<div class="row2"><div><label class="f">Cost price (₹)</label><input id="c" type="number" inputmode="numeric" value="800"></div><div><label class="f">Sell price (₹)</label><input id="s" type="number" inputmode="numeric" value="1000"></div></div>`,calc:()=>{let c=+v('c'),s=+v('s'),pr=s-c;return `<div class="lbl">Profit</div><div class="big">${RS(pr)}</div><div class="rrow"><span>Margin (on sell)</span><b>${s?(pr/s*100).toFixed(2):0}%</b></div><div class="rrow"><span>Markup (on cost)</span><b>${c?(pr/c*100).toFixed(2):0}%</b></div>`;}},
{id:'lcm',cat:'Utility',ic:'🔢',name:'LCM & HCF',desc:'2 number ka LCM/HCF',fields:`<div class="row2"><div><label class="f">Number 1</label><input id="a" type="number" inputmode="numeric" value="12"></div><div><label class="f">Number 2</label><input id="b" type="number" inputmode="numeric" value="18"></div></div>`,calc:()=>{let a=Math.abs(+v('a')),b=Math.abs(+v('b'));if(!a||!b)return '<div class="hint">Dono number daalein.</div>';let x=a,y=b;while(y){[x,y]=[y,x%y];}let hcf=x,lcm=a*b/hcf;return `<div class="lbl">HCF (GCD)</div><div class="big">${hcf}</div><div class="rrow"><span>LCM</span><b>${lcm}</b></div>`;}},
{id:'simplify',cat:'Utility',ic:'➗',name:'Fraction Simplify',desc:'Fraction chhota karo',fields:`<div class="row2"><div><label class="f">Numerator (upar)</label><input id="a" type="number" inputmode="numeric" value="24"></div><div><label class="f">Denominator (neeche)</label><input id="b" type="number" inputmode="numeric" value="36"></div></div>`,calc:()=>{let a=+v('a'),b=+v('b');if(!b)return '<div class="hint">Denominator 0 nahi.</div>';let x=Math.abs(a),y=Math.abs(b);while(y){[x,y]=[y,x%y];}let g=x||1;return `<div class="lbl">Simplified</div><div class="big">${a/g} / ${b/g}</div><div class="rrow"><span>Decimal</span><b>${(a/b).toFixed(4)}</b></div>`;}},
{id:'love',cat:'Rozana',ic:'❤️',name:'Love Calculator',desc:'Bas mazaak ke liye',fields:`<label class="f">Pehla naam</label><input id="a" type="text"><label class="f">Doosra naam</label><input id="b" type="text"><button class="btn" onclick="doLove()">Calculate ❤️</button><div id="lout" class="result"></div>`,custom:true},
{id:'itax',cat:'Loan/Tax',ic:'🧾',name:'Income Tax (New Regime)',desc:'FY 2025-26 tax estimate',pop:1,fields:`<label class="f">Saalana income (₹)</label><input id="a" type="number" inputmode="numeric" value="1200000"><label class="f">Type</label><select id="t"><option value="1">Salaried (₹75k std deduction)</option><option value="0">Other</option></select>`,calc:()=>{let g=+v('a'),sd=+v('t')==1?75000:0,ti=Math.max(0,g-sd);let slabs=[[400000,0],[800000,.05],[1200000,.10],[1600000,.15],[2000000,.20],[2400000,.25],[Infinity,.30]];let tax=0,prev=0;for(let[lim,rate]of slabs){if(ti>prev){let amt=Math.min(ti,lim)-prev;tax+=amt*rate;prev=lim;}else break;}if(ti<=1200000)tax=0;let cess=tax*0.04,total=tax+cess;return `<div class="lbl">Tax (anuman, New Regime)</div><div class="big">${RS(total)}</div><div class="rrow"><span>Taxable income</span><b>${RS(ti)}</b></div><div class="rrow"><span>Tax + 4% cess</span><b>${RS(tax)} + ${RS(cess)}</b></div><div class="hint">₹12 lakh tak taxable income par tax 0 (87A rebate). Ye sirf anuman — taaza slab incometax.gov.in par confirm karein.</div>${DISC}`;}},
{id:'pomis',cat:'Nivesh',ic:'📮',name:'Post Office MIS',desc:'Monthly income scheme',fields:`<label class="f">Jama rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="900000"><label class="f">Byaj % (abhi ~7.4)</label><input id="r" type="number" inputmode="decimal" value="7.4" step="0.1">`,calc:()=>{let P=+v('a'),r=+v('r')/100,mi=P*r/12;return `<div class="lbl">Har mahine income</div><div class="big">${RS(mi)}</div><div class="rrow"><span>5 saal me total byaj</span><b>${RS(mi*60)}</b></div><div class="hint">Single account max ₹9 lakh, joint ₹15 lakh. Byaj dar sarkar har quarter tay karti.</div>`;}},
{id:'kvp',cat:'Nivesh',ic:'🌾',name:'KVP (Paisa Double)',desc:'Kisan Vikas Patra',fields:`<label class="f">Jama rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><label class="f">Byaj % (abhi ~7.5)</label><input id="r" type="number" inputmode="decimal" value="7.5" step="0.1">`,calc:()=>{let P=+v('a'),r=+v('r'),yrs=Math.log(2)/Math.log(1+r/100),mon=Math.round(yrs*12);return `<div class="lbl">Paisa double (${RS(P*2)})</div><div class="big">~${Math.floor(mon/12)} saal ${mon%12} mahine</div><div class="rrow"><span>Maturity value</span><b>${RS(P*2)}</b></div><div class="hint">KVP me paisa double ho jaata. Time byaj dar par depend — abhi ka daal.</div>`;}},
{id:'scss',cat:'Nivesh',ic:'👵',name:'SCSS (Senior Citizen)',desc:'Quarterly pension income',fields:`<label class="f">Jama rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="1500000"><label class="f">Byaj % (abhi ~8.2)</label><input id="r" type="number" inputmode="decimal" value="8.2" step="0.1">`,calc:()=>{let P=+v('a'),r=+v('r')/100,qi=P*r/4;return `<div class="lbl">Har 3 mahine (quarter) income</div><div class="big">${RS(qi)}</div><div class="rrow"><span>Saalana byaj</span><b>${RS(P*r)}</b></div><div class="rrow"><span>5 saal me total byaj</span><b>${RS(P*r*5)}</b></div><div class="hint">60+ umar ke liye. Max ₹30 lakh. Byaj dar sarkar tay karti.</div>`;}},
{id:'prepay',cat:'Loan/Tax',ic:'✂️',name:'Loan Prepayment Saving',desc:'Ek baar extra bharo, kitna bacha',fields:`<label class="f">Loan amount (₹)</label><input id="a" type="number" inputmode="numeric" value="2000000"><div class="row3"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="9" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="20"></div><div><label class="f">Ek baar prepay (₹)</label><input id="p" type="number" inputmode="numeric" value="200000"></div></div>`,calc:()=>{let P=+v('a'),R=+v('r')/12/100,N=+v('y')*12,pre=+v('p');if(R<=0||N<=0)return '<div class="hint">Sahi value daalein.</div>';let emi=P*R*Math.pow(1+R,N)/(Math.pow(1+R,N)-1);let noPre=emi*N-P;let bal=P-pre;if(bal<0)bal=0;let m=0,ip=0;while(bal>0&&m<1000){let intr=bal*R,pr=emi-intr;if(pr<=0)break;if(bal<=emi){ip+=intr;bal=0;m++;break;}bal-=pr;ip+=intr;m++;}let saved=noPre-ip,monSaved=N-m;return `<div class="lbl">Byaj bacha (anuman)</div><div class="big" style="color:#0F766E">${RS(saved)}</div><div class="rrow"><span>Loan jaldi khatam</span><b>~${Math.floor(monSaved/12)} saal ${monSaved%12} mahine</b></div><div class="rrow"><span>Monthly EMI</span><b>${RS(emi)}</b></div><div class="hint">Shuruat me kiya prepayment sabse zyada bachata hai.</div>${DISC}`;}},
{id:'emergency',cat:'Nivesh',ic:'🛟',name:'Emergency Fund',desc:'Kitna emergency fund chahiye',fields:`<label class="f">Har mahine kharch (₹)</label><input id="a" type="number" inputmode="numeric" value="30000"><label class="f">Kitne mahine ka</label><select id="m"><option value="6">6 mahine (recommended)</option><option value="3">3 mahine</option><option value="12">12 mahine</option></select>`,calc:()=>{let e=+v('a'),m=+v('m');return `<div class="lbl">Emergency fund chahiye</div><div class="big">${RS(e*m)}</div><div class="rrow"><span>${m} mahine ka kharch</span><b>${RS(e*m)}</b></div><div class="hint">Ise FD/liquid fund me rakhein — jab job chhoot jaye ya emergency ho, kaam aaye.</div>`;}},
{id:'marks',cat:'Utility',ic:'📝',name:'Marks Percentage',desc:'Number se percentage',fields:`<div class="row2"><div><label class="f">Mile marks</label><input id="a" type="number" inputmode="numeric" value="425"></div><div><label class="f">Total marks</label><input id="b" type="number" inputmode="numeric" value="500"></div></div>`,calc:()=>{let o=+v('a'),t=+v('b');if(!t)return '<div class="hint">Total marks daalein.</div>';let p=o/t*100;return `<div class="lbl">Percentage</div><div class="big">${p.toFixed(2)}%</div><div class="rrow"><span>${o} / ${t}</span><b>${p.toFixed(2)}%</b></div>`;}},
{id:'cgpa',cat:'Utility',ic:'🎓',name:'CGPA to Percentage',desc:'CGPA ko % me badlo',fields:`<div class="row2"><div><label class="f">CGPA</label><input id="a" type="number" inputmode="decimal" value="8.5" step="0.01"></div><div><label class="f">Multiplier (aam: 9.5)</label><input id="m" type="number" inputmode="decimal" value="9.5" step="0.1"></div></div>`,calc:()=>{let c=+v('a'),m=+v('m');return `<div class="lbl">Percentage</div><div class="big">${(c*m).toFixed(2)}%</div><div class="hint">Aam formula: CGPA × 9.5 (CBSE). Apne board/university ka formula confirm karein.</div>`;}},
{id:'homeaff',cat:'Loan/Tax',ic:'🏠',name:'Home Loan Eligibility',desc:'Kitna loan mil sakta',fields:`<label class="f">Monthly income (₹)</label><input id="a" type="number" inputmode="numeric" value="60000"><div class="row3"><div><label class="f">Chalu EMI (₹)</label><input id="e" type="number" inputmode="numeric" value="0"></div><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="9" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="20"></div></div>`,calc:()=>{let inc=+v('a'),ex=+v('e'),R=+v('r')/12/100,N=+v('y')*12;let maxEmi=inc*0.5-ex;if(maxEmi<=0)return '<div class="hint">Income ke hisaab se EMI ki gunjaish nahi.</div>';let loan=maxEmi*(Math.pow(1+R,N)-1)/(R*Math.pow(1+R,N));return `<div class="lbl">Anumanit loan eligibility</div><div class="big">${RS(loan)}</div><div class="rrow"><span>Max affordable EMI</span><b>${RS(maxEmi)}</b></div><div class="hint">Bank aam taur par income ka ~50% tak EMI dete. Asli eligibility bank tay karta.</div>${DISC}`;}},
{id:'rentyield',cat:'Nivesh',ic:'🏢',name:'Rental Yield',desc:'Property ka rental return %',fields:`<label class="f">Property value (₹)</label><input id="a" type="number" inputmode="numeric" value="5000000"><label class="f">Monthly rent (₹)</label><input id="b" type="number" inputmode="numeric" value="15000">`,calc:()=>{let val=+v('a'),rent=+v('b');if(!val)return '<div class="hint">Property value daalein.</div>';let annual=rent*12,y=annual/val*100;return `<div class="lbl">Rental yield (saalana)</div><div class="big">${y.toFixed(2)}%</div><div class="rrow"><span>Saalana rent</span><b>${RS(annual)}</b></div><div class="hint">Bharat me aam residential yield ~2-4%. Isme maintenance/tax nahi juda.</div>`;}},
{id:'unitprice',cat:'Rozana',ic:'🛒',name:'Price Compare (per unit)',desc:'Kaunsa pack sasta',fields:`<div class="row2"><div><label class="f">Pack A daam (₹)</label><input id="p1" type="number" inputmode="numeric" value="100"></div><div><label class="f">Pack A qty</label><input id="q1" type="number" inputmode="numeric" value="500"></div></div><div class="row2"><div><label class="f">Pack B daam (₹)</label><input id="p2" type="number" inputmode="numeric" value="180"></div><div><label class="f">Pack B qty</label><input id="q2" type="number" inputmode="numeric" value="1000"></div></div>`,calc:()=>{let p1=+v('p1'),q1=+v('q1'),p2=+v('p2'),q2=+v('q2');if(!q1||!q2)return '<div class="hint">Quantity daalein.</div>';let u1=p1/q1,u2=p2/q2,cheap=u1<u2?'Pack A':'Pack B';return `<div class="lbl">Sasta: ${cheap}</div><div class="big">${cheap}</div><div class="rrow"><span>Pack A per unit</span><b>₹${u1.toFixed(3)}</b></div><div class="rrow"><span>Pack B per unit</span><b>₹${u2.toFixed(3)}</b></div>`;}},
{id:'brokerage',cat:'Trading',ic:'🧮',name:'Brokerage & Charges',desc:'Equity delivery/intraday ke charges',pop:1,fields:`<div class="row2"><div><label class="f">Buy price (₹)</label><input id="bp" type="number" inputmode="numeric" value="100"></div><div><label class="f">Sell price (₹)</label><input id="sp" type="number" inputmode="numeric" value="105"></div></div><div class="row2"><div><label class="f">Quantity</label><input id="q" type="number" inputmode="numeric" value="100"></div><div><label class="f">Type</label><select id="t"><option value="del">Delivery</option><option value="intra">Intraday</option></select></div></div>`,calc:()=>{let bp=+v('bp'),sp=+v('sp'),q=+v('q'),t=v('t');if(!bp||!sp||!q)return '<div class="hint">Sahi value daalein.</div>';let bv=bp*q,sv=sp*q,to=bv+sv,brok,stt,stamp;if(t==='intra'){brok=Math.min(20,bv*0.0003)+Math.min(20,sv*0.0003);stt=sv*0.00025;stamp=bv*0.00003;}else{brok=0;stt=(bv+sv)*0.001;stamp=bv*0.00015;}let exch=to*0.0000297,sebi=to*0.000001,gst=(brok+exch)*0.18,ch=brok+stt+exch+sebi+stamp+gst,gross=(sp-bp)*q,net=gross-ch;return `<div class="lbl">Net profit (charges ke baad)</div><div class="big" style="color:${net>=0?'#0F766E':'#B91C1C'}">${RS2(net)}</div><div class="rrow"><span>Gross P&L</span><b>${RS2(gross)}</b></div><div class="rrow"><span>Total charges</span><b>${RS2(ch)}</b></div><div class="rrow"><span>Brokerage + GST</span><b>${RS2(brok+gst)}</b></div><div class="rrow"><span>STT + stamp + exch + SEBI</span><b>${RS2(stt+stamp+exch+sebi)}</b></div><div class="hint">Discount broker (jaise Zerodha) ka anuman. Aapke broker par thoda alag ho sakta.</div>${DISC}`;}},
{id:'sltp',cat:'Trading',ic:'🎯',name:'Stop-Loss & Target Price',desc:'Entry se SL aur target nikaalo',fields:`<label class="f">Entry price (₹)</label><input id="e" type="number" inputmode="numeric" value="500"><div class="row2"><div><label class="f">Stop-loss %</label><input id="sl" type="number" inputmode="decimal" value="2" step="0.1"></div><div><label class="f">Target %</label><input id="tg" type="number" inputmode="decimal" value="4" step="0.1"></div></div>`,calc:()=>{let e=+v('e'),sl=+v('sl'),tg=+v('tg');if(!e)return '<div class="hint">Entry price daalein.</div>';let slp=e*(1-sl/100),tgp=e*(1+tg/100),rr=sl>0?tg/sl:0;return `<div class="lbl">Long trade ke liye</div><div class="rrow"><span>Stop-loss price</span><b style="color:#B91C1C">${RS2(slp)}</b></div><div class="rrow"><span>Target price</span><b style="color:#0F766E">${RS2(tgp)}</b></div><div class="rrow"><span>Risk : Reward</span><b>1 : ${rr.toFixed(2)}</b></div><div class="hint">RR 1:2 ya usse behtar achha maana jaata hai. Short trade me SL upar, target neeche hoga.</div>`;}},
{id:'dti',cat:'Loan/Tax',ic:'⚖️',name:'Debt-to-Income (DTI)',desc:'Income ka kitna % EMI me',fields:`<label class="f">Monthly income (₹)</label><input id="a" type="number" inputmode="numeric" value="60000"><label class="f">Total monthly EMI (₹)</label><input id="e" type="number" inputmode="numeric" value="18000">`,calc:()=>{let inc=+v('a'),emi=+v('e');if(!inc)return '<div class="hint">Income daalein.</div>';let d=emi/inc*100,r=d<36?'Achha ✅':d<=43?'Theek ⚠️':'Zyada ❌';return `<div class="lbl">DTI ratio</div><div class="big">${d.toFixed(1)}%</div><div class="rrow"><span>Rating</span><b>${r}</b></div><div class="hint">Bank aam taur par 36% se kam DTI pasand karte. 43% se upar loan milna mushkil.</div>`;}},
{id:'fire',cat:'Nivesh',ic:'🔥',name:'FIRE Number',desc:'Jaldi retire ke liye kitna paisa',fields:`<label class="f">Har mahine kharch (₹)</label><input id="a" type="number" inputmode="numeric" value="40000"><label class="f">Safe withdrawal rate %</label><input id="r" type="number" inputmode="decimal" value="4" step="0.5">`,calc:()=>{let me=+v('a'),rate=+v('r');if(!me||!rate)return '<div class="hint">Value daalein.</div>';let annual=me*12,fire=annual/(rate/100);return `<div class="lbl">FIRE number (retirement corpus)</div><div class="big">${RS(fire)}</div><div class="rrow"><span>Saalana kharch</span><b>${RS(annual)}</b></div><div class="hint">Itna corpus ho to ${rate}% nikaal kar bina naukri ke kharch chal sakta (4% rule). Inflation alag se dhyan rakhein.</div>${DISC}`;}},
{id:'nw',cat:'Nivesh',ic:'💼',name:'Net Worth',desc:'Aapki asli sampatti',fields:`<label class="f">Total assets (₹) — cash, FD, property, gold, shares</label><input id="a" type="number" inputmode="numeric" value="2500000"><label class="f">Total liabilities (₹) — loan, karza</label><input id="l" type="number" inputmode="numeric" value="800000">`,calc:()=>{let a=+v('a'),l=+v('l'),nw=a-l;return `<div class="lbl">Net worth</div><div class="big" style="color:${nw>=0?'#0F766E':'#B91C1C'}">${RS(nw)}</div><div class="rrow"><span>Assets</span><b>${RS(a)}</b></div><div class="rrow"><span>Liabilities</span><b>${RS(l)}</b></div><div class="hint">Net worth = jo aapke paas hai − jo aap par karza hai. Har saal badhna chahiye.</div>`;}},
{id:'saverate',cat:'Nivesh',ic:'🐖',name:'Savings Rate',desc:'Income ka kitna % bachate ho',fields:`<label class="f">Monthly income (₹)</label><input id="a" type="number" inputmode="numeric" value="50000"><label class="f">Monthly savings/investment (₹)</label><input id="s" type="number" inputmode="numeric" value="12000">`,calc:()=>{let inc=+v('a'),s=+v('s');if(!inc)return '<div class="hint">Income daalein.</div>';let r=s/inc*100;return `<div class="lbl">Savings rate</div><div class="big">${r.toFixed(1)}%</div><div class="hint">20% se upar achha maana jaata. Jitna zyada bachao, utni jaldi financial freedom.</div>`;}},
{id:'bmr',cat:'Sehat',ic:'🔋',name:'BMR (Calorie Need)',desc:'Din bhar ki calorie zaroorat',fields:`<div class="row2"><div><label class="f">Weight (kg)</label><input id="w" type="number" inputmode="numeric" value="70"></div><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div></div><div class="row2"><div><label class="f">Umar (saal)</label><input id="a" type="number" inputmode="numeric" value="30"></div><div><label class="f">Gender</label><select id="g"><option value="m">Purush</option><option value="f">Mahila</option></select></div></div>`,calc:()=>{let w=+v('w'),h=+v('h'),a=+v('a'),g=v('g');if(!w||!h||!a)return '<div class="hint">Value daalein.</div>';let bmr=g==='m'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161;let maint=bmr*1.4;return `<div class="lbl">BMR (aaram ki halat me)</div><div class="big">${Math.round(bmr)} <span style="font-size:1rem">cal/din</span></div><div class="rrow"><span>Halka active (maintain)</span><b>~${Math.round(maint)} cal/din</b></div><div class="hint">BMR = jitni calorie sharir bina kuch kiye jalata hai. Ye sirf jaankari hai — diet/health ke liye doctor se salah lein.</div>`+MEDDISC;}},
{id:'sleep',cat:'Rozana',ic:'😴',name:'Sleep Time',desc:'Kab soyein taaki taaza uthein',fields:`<label class="f">Subah uthna hai (HH:MM, 24hr)</label><input id="w" type="text" value="06:30" placeholder="06:30">`,calc:()=>{let x=(v('w')||'').split(':');if(x.length!==2)return '<div class="hint">Time aise daalein: 06:30</div>';let h=+x[0],m=+x[1];if(isNaN(h)||isNaN(m))return '<div class="hint">Sahi time daalein (06:30).</div>';let wake=h*60+m;let fmt=t=>{t=((t%1440)+1440)%1440;let H=Math.floor(t/60),M=t%60;let ap=H<12?'AM':'PM';let h12=H%12||12;return `${h12}:${String(M).padStart(2,'0')} ${ap}`;};let opt=[6,5,4].map(c=>`<div class="rrow"><span>${c} cycle (${(c*1.5).toFixed(1)} ghante neend)</span><b>${fmt(wake-(c*90+15))}</b></div>`).join('');return `<div class="lbl">Sone ka sahi samay</div>${opt}<div class="hint">Neend 90-min cycle me hoti hai. In samay me soyein to beech cycle me alarm nahi bajega, taaza uthenge (15 min neend aane ka joda).</div>`;}},
{id:'dateadd',cat:'Utility',ic:'📅',name:'Date + / − Days',desc:'Kisi date me din jodo/ghatao',fields:`<label class="f">Date</label><input id="d" type="date"><label class="f">Kitne din (+ aage, − peeche)</label><input id="n" type="number" inputmode="numeric" value="90">`,calc:()=>{let d=v('d'),n=+v('n');if(!d)return '<div class="hint">Date chunein.</div>';let dt=new Date(d);if(isNaN(dt))return '<div class="hint">Sahi date chunein.</div>';dt.setDate(dt.getDate()+n);let days=['Ravi','Som','Mangal','Budh','Guru','Shukra','Shani'];return `<div class="lbl">${n>=0?n+' din baad':(-n)+' din pehle'}</div><div class="big">${dt.toLocaleDateString('en-GB')}</div><div class="rrow"><span>Din</span><b>${days[dt.getDay()]}war</b></div>`;}},
{id:'downpay',cat:'Loan/Tax',ic:'🏦',name:'Down Payment Planner',desc:'Har mahine kitna bachana',fields:`<label class="f">Target rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="500000"><div class="row2"><div><label class="f">Kitne mahine</label><input id="n" type="number" inputmode="numeric" value="36"></div><div><label class="f">Return % (saalana)</label><input id="r" type="number" inputmode="decimal" value="8" step="0.5"></div></div>`,calc:()=>{let fv=+v('a'),n=+v('n'),ar=+v('r');if(!fv||!n)return '<div class="hint">Value daalein.</div>';let r=ar/12/100,m=r>0?fv*r/(Math.pow(1+r,n)-1):fv/n;return `<div class="lbl">Har mahine bachao</div><div class="big">${RS(m)}</div><div class="rrow"><span>${n} mahine me jama</span><b>${RS(m*n)}</b></div><div class="rrow"><span>Byaj/growth se</span><b>${RS(fv-m*n)}</b></div><div class="hint">SIP/RD me daal kar ye target paa sakte hain.</div>${DISC}`;}},
{id:'realret',cat:'Nivesh',ic:'📉',name:'Real Return (Inflation ke baad)',desc:'Asli return kitna bacha',fields:`<div class="row2"><div><label class="f">Return % (nominal)</label><input id="r" type="number" inputmode="decimal" value="8" step="0.1"></div><div><label class="f">Inflation %</label><input id="i" type="number" inputmode="decimal" value="6" step="0.1"></div></div>`,calc:()=>{let nom=+v('r'),inf=+v('i');let real=((1+nom/100)/(1+inf/100)-1)*100;return `<div class="lbl">Real return (asli)</div><div class="big" style="color:${real>=0?'#0F766E':'#B91C1C'}">${real.toFixed(2)}%</div><div class="hint">FD ${nom}% de rahi par inflation ${inf}% hai — to asli badhotri sirf ${real.toFixed(2)}%. Isi liye sirf FD se paisa nahi badhta.</div>`;}},
{id:'beunits',cat:'Utility',ic:'📊',name:'Business Breakeven',desc:'Kitna bechne par nafa shuru',fields:`<label class="f">Fixed cost (₹) — kiraya, salary</label><input id="f" type="number" inputmode="numeric" value="50000"><div class="row2"><div><label class="f">Bikri daam/unit (₹)</label><input id="p" type="number" inputmode="numeric" value="200"></div><div><label class="f">Laagat/unit (₹)</label><input id="c" type="number" inputmode="numeric" value="120"></div></div>`,calc:()=>{let fc=+v('f'),p=+v('p'),c=+v('c');if(p<=c)return '<div class="hint">Bikri daam laagat se zyada hona chahiye.</div>';let u=fc/(p-c);return `<div class="lbl">Breakeven — itna bechna hoga</div><div class="big">${Math.ceil(u)} unit</div><div class="rrow"><span>Breakeven bikri</span><b>${RS(Math.ceil(u)*p)}</b></div><div class="rrow"><span>Har unit se margin</span><b>${RS(p-c)}</b></div><div class="hint">Isse zyada bechoge to nafa shuru. Chhote business ke liye zaroori number.</div>`;}},
{id:'budget',cat:'Nivesh',ic:'🧮',name:'50/30/20 Budget',desc:'Salary ko needs/wants/savings me baanto',pop:1,fields:`<label class="f">Monthly in-hand salary (₹)</label><input id="a" type="number" inputmode="numeric" value="40000">`,calc:()=>{let i=+v('a');if(!i)return '<div class="hint">Salary daalein.</div>';return `<div class="lbl">Salary ka hisaab (50/30/20)</div><div class="rrow"><span>Needs (50%) — rent, ration, bills</span><b>${RS(i*.5)}</b></div><div class="rrow"><span>Wants (30%) — shauk, mauj</span><b>${RS(i*.3)}</b></div><div class="rrow"><span>Savings/Loan (20%)</span><b>${RS(i*.2)}</b></div><div class="hint">Ye shuruaati dhaancha hai — kam salary/bade shehar me needs zyada ho sakti. Jitna ho sake, savings 20% se kam mat karein.</div>`;}},
{id:'taxcompare',cat:'Loan/Tax',ic:'⚖️',name:'Old vs New Tax Regime',desc:'Kaunsa regime kam tax dega',pop:1,fields:`<label class="f">Saalana income (₹)</label><input id="a" type="number" inputmode="numeric" value="1500000"><label class="f">Old regime deductions (80C, HRA, home loan… ₹)</label><input id="d" type="number" inputmode="numeric" value="200000"><label class="f">Salaried?</label><select id="s"><option value="1">Haan (std deduction milega)</option><option value="0">Nahi</option></select>`,calc:()=>{let g=+v('a'),ded=+v('d'),sal=+v('s')==1;function tax(ti,slabs,reb){if(ti<=reb)return 0;let t=0,prev=0;for(let[lim,rate]of slabs){if(ti>prev){t+=(Math.min(ti,lim)-prev)*rate;prev=lim;}else break;}return t;}let nti=Math.max(0,g-(sal?75000:0));let ns=[[400000,0],[800000,.05],[1200000,.10],[1600000,.15],[2000000,.20],[2400000,.25],[Infinity,.30]];let ntot=tax(nti,ns,1200000)*1.04;let oti=Math.max(0,g-(sal?50000:0)-ded);let os=[[250000,0],[500000,.05],[1000000,.20],[Infinity,.30]];let otot=tax(oti,os,500000)*1.04;let better=ntot<=otot?'New Regime':'Old Regime';return `<div class="lbl">Kam tax: ${better}</div><div class="big">${RS(Math.min(ntot,otot))}</div><div class="rrow"><span>New Regime tax</span><b>${RS(ntot)}</b></div><div class="rrow"><span>Old Regime tax</span><b>${RS(otot)}</b></div><div class="rrow"><span>${better} se bachat</span><b>${RS(Math.abs(ntot-otot))}</b></div><div class="hint">4% cess shamil. New regime me ₹12L tak taxable par tax 0. Old regime aapke deductions par depend. Ye anuman — taaza slab incometax.gov.in par confirm karein.</div>${DISC}`;}},
{id:'crorepati',cat:'Nivesh',ic:'💰',name:'Kab Banoge Crorepati',desc:'SIP se ₹1 crore kitne saal me',pop:1,fields:`<label class="f">Har mahine SIP (₹)</label><input id="a" type="number" inputmode="numeric" value="10000"><div class="row2"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Target (₹)</label><input id="t" type="number" inputmode="numeric" value="10000000"></div></div>`,calc:()=>{let M=+v('a'),r=+v('r')/12/100,FV=+v('t');if(M<=0||r<=0||FV<=0)return '<div class="hint">Sahi value daalein.</div>';let n=Math.log(1+FV*r/(M*(1+r)))/Math.log(1+r);let inv=M*n;return `<div class="lbl">${RS(FV)} banega</div><div class="big">${Math.floor(n/12)} saal ${Math.round(n%12)} mahine</div><div class="rrow"><span>Total invest</span><b>${RS(inv)}</b></div><div class="rrow"><span>Munafa (est.)</span><b>${RS(FV-inv)}</b></div><div class="hint">${v('r')}% return maan kar. Return guaranteed nahi — market par depend.</div>${DISC}`;}},
{id:'sipdelay',cat:'Nivesh',ic:'⏰',name:'SIP Delay Ka Nuksan',desc:'Der se shuru karne ka farak',fields:`<label class="f">Har mahine SIP (₹)</label><input id="a" type="number" inputmode="numeric" value="10000"><div class="row3"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Kul saal</label><input id="y" type="number" inputmode="numeric" value="25"></div><div><label class="f">Der (saal)</label><input id="d" type="number" inputmode="numeric" value="5"></div></div>`,calc:()=>{let M=+v('a'),r=+v('r')/12/100,Y=+v('y'),D=+v('d');if(M<=0||Y<=0||D<0||D>=Y)return '<div class="hint">Der, kul saal se kam honi chahiye.</div>';let fv=n=>r?M*((Math.pow(1+r,n)-1)/r)*(1+r):M*n;let now=fv(Y*12),late=fv((Y-D)*12);return `<div class="lbl">${D} saal der ka nuksan</div><div class="big" style="color:#B91C1C">${RS(now-late)}</div><div class="rrow"><span>Abhi shuru (${Y} saal)</span><b>${RS(now)}</b></div><div class="rrow"><span>${D} saal baad shuru (${Y-D} saal)</span><b>${RS(late)}</b></div><div class="hint">Sirf ${D} saal der = ${RS(now-late)} kam. SIP jitni jaldi shuru, utna behtar.</div>${DISC}`;}},
{id:'tds',cat:'Loan/Tax',ic:'🧾',name:'TDS Calculator',desc:'Kis rakam par kitna TDS katega',fields:`<label class="f">Rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><label class="f">Kis cheez par TDS?</label><select id="t"><option value="10">FD/Byaj (194A) — 10%</option><option value="10">Rent property (194I) — 10%</option><option value="2">Contractor (194C) — 2%</option><option value="10">Professional fees (194J) — 10%</option><option value="5">Commission (194H) — 5%</option><option value="30">Lottery/Game (194B) — 30%</option></select><label class="f">PAN diya hai?</label><select id="p"><option value="1">Haan</option><option value="0">Nahi (rate zyada)</option></select>`,calc:()=>{let amt=+v('a'),rate=+v('t'),pan=+v('p')==1;if(!amt)return '<div class="hint">Rakam daalein.</div>';let r=pan?rate:Math.max(rate,20);let tds=amt*r/100;return `<div class="lbl">TDS katega (${r}%)</div><div class="big">${RS(tds)}</div><div class="rrow"><span>Haath me aayega</span><b>${RS(amt-tds)}</b></div><div class="hint">Ye aam rate hai. PAN na dene par TDS 20% (ya zyada). Salary par TDS slab ke hisaab se. Asli rate/limit ke liye CA ya incometax.gov.in dekhein.</div>${DISC}`;}},
{id:'buyrent',cat:'Loan/Tax',ic:'🏠',name:'Ghar: Kharidein ya Kiraya',desc:'EMI vs kiraya — kya sasta',fields:`<label class="f">Ghar ki keemat (₹)</label><input id="p" type="number" inputmode="numeric" value="5000000"><div class="row2"><div><label class="f">Down payment (₹)</label><input id="d" type="number" inputmode="numeric" value="1000000"></div><div><label class="f">Loan byaj %</label><input id="r" type="number" inputmode="decimal" value="8.5" step="0.1"></div></div><div class="row2"><div><label class="f">Loan saal</label><input id="y" type="number" inputmode="numeric" value="20"></div><div><label class="f">Abhi kiraya/mahina (₹)</label><input id="rent" type="number" inputmode="numeric" value="18000"></div></div>`,calc:()=>{let P=+v('p')-+v('d'),r=+v('r')/12/100,n=+v('y')*12,rent=+v('rent');if(P<=0)return '<div class="hint">Down payment ghar ki keemat se kam ho.</div>';let emi=r?P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1):P/n;let diff=emi-rent;return `<div class="lbl">Home loan EMI</div><div class="big">${RS(emi)}/mahina</div><div class="rrow"><span>Abhi ka kiraya</span><b>${RS(rent)}/mahina</b></div><div class="rrow"><span>Farak</span><b style="color:${diff>0?'#B91C1C':'#0F766E'}">${diff>0?'+':''}${RS(diff)}</b></div><div class="hint">${diff>0?'EMI kiraye se '+RS(diff)+' zyada — par ghar aapka ban raha, kiraya wapas nahi aata.':'EMI kiraye se kam/barabar — kharidna faydemand lag raha.'} Maintenance, property growth aur rehne ke saal bhi socho.</div>${DISC}`;}},
{id:'hourly',cat:'Loan/Tax',ic:'⏰',name:'Salary → Per Hour',desc:'Mahine se ghanta/din ki kamai',fields:`<label class="f">Monthly salary (₹)</label><input id="a" type="number" inputmode="numeric" value="40000"><div class="row2"><div><label class="f">Din/mahina kaam</label><input id="d" type="number" inputmode="numeric" value="26"></div><div><label class="f">Ghante/din</label><input id="h" type="number" inputmode="numeric" value="8"></div></div>`,calc:()=>{let s=+v('a'),d=+v('d'),h=+v('h');if(!s||!d||!h)return '<div class="hint">Value daalein.</div>';let day=s/d,hour=day/h;return `<div class="lbl">Per ghanta kamai</div><div class="big">${RS(hour)}</div><div class="rrow"><span>Per din</span><b>${RS(day)}</b></div><div class="rrow"><span>Per minute</span><b>${RS2(hour/60)}</b></div><div class="hint">Freelancer/part-time rate tay karne me kaam aata. Extra kaam ya overtime ki value bhi isi se samajh aati.</div>`;}},
{id:'appliancebill',cat:'Rozana',ic:'🔌',name:'Appliance Bijli Kharch',desc:'AC/geyser/fridge ka mahine ka bill',fields:`<label class="f">Power (watt)</label><input id="w" type="number" inputmode="numeric" value="1500"><div class="row3"><div><label class="f">Ghante/din</label><input id="h" type="number" inputmode="numeric" value="6"></div><div><label class="f">Din/mahina</label><input id="d" type="number" inputmode="numeric" value="30"></div><div><label class="f">₹/unit</label><input id="r" type="number" inputmode="decimal" value="8" step="0.5"></div></div>`,calc:()=>{let w=+v('w'),h=+v('h'),d=+v('d'),r=+v('r');if(!w||!h)return '<div class="hint">Value daalein.</div>';let units=w*h*d/1000;let cost=units*r;return `<div class="lbl">Mahine ka kharch</div><div class="big">${RS(cost)}</div><div class="rrow"><span>Units (kWh)/mahina</span><b>${units.toFixed(1)}</b></div><div class="rrow"><span>Per din</span><b>${RS(cost/d)}</b></div><div class="hint">1 unit = 1000 watt 1 ghante chalane par. AC, geyser, iron sabse zyada bijli khaate. ₹/unit apne bijli bill se dekhein.</div>`;}},
{id:'whr',cat:'Sehat',ic:'📏',name:'Waist-to-Height Ratio',desc:'Pet ki charbi ka signal',fields:`<div class="row2"><div><label class="f">Kamar (waist) cm</label><input id="w" type="number" inputmode="numeric" value="85"></div><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div></div>`,calc:()=>{let w=+v('w'),h=+v('h');if(!w||!h)return '<div class="hint">Value daalein.</div>';let r=w/h;let msg=r<0.5?'0.5 se kam — aam taur par theek maana jaata':'0.5 se zyada — pet ki charbi par dhyan dena behtar';return `<div class="lbl">Waist-to-Height Ratio</div><div class="big">${r.toFixed(2)}</div><div class="hint">${msg}. Ye kai baar BMI se accha signal deta pet ki charbi ke liye. Sirf jaankari — sehat ke liye doctor se salah lein.</div>`+MEDDISC;}},
{id:'goallump',cat:'Nivesh',ic:'🎯',name:'Goal ke liye Lumpsum',desc:'Target ke liye aaj kitna lagao',fields:`<label class="f">Target rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="1000000"><div class="row2"><div><label class="f">Return %</label><input id="r" type="number" inputmode="decimal" value="12" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="10"></div></div>`,calc:()=>{let FV=+v('a'),r=+v('r')/100,y=+v('y');if(!FV||y<0)return '<div class="hint">Value daalein.</div>';let PV=FV/Math.pow(1+r,y);return `<div class="lbl">Aaj itna lagana hoga (lumpsum)</div><div class="big">${RS(PV)}</div><div class="rrow"><span>${y} saal baad banega</span><b>${RS(FV)}</b></div><div class="rrow"><span>Growth</span><b>${RS(FV-PV)}</b></div><div class="hint">${v('r')}% return maan kar. Ek saath itna na ho to SIP Goal calculator try karein.</div>${DISC}`;}},
{id:'exammarks',cat:'Utility',ic:'📝',name:'Exam Target Marks',desc:'Target ke liye kitne marks chahiye',fields:`<div class="row2"><div><label class="f">Ab tak mile marks</label><input id="o" type="number" inputmode="numeric" value="120"></div><div><label class="f">Ab tak ke total</label><input id="m" type="number" inputmode="numeric" value="200"></div></div><div class="row2"><div><label class="f">Baaki exam ke total</label><input id="f" type="number" inputmode="numeric" value="100"></div><div><label class="f">Target overall %</label><input id="t" type="number" inputmode="numeric" value="75"></div></div>`,calc:()=>{let o=+v('o'),m=+v('m'),f=+v('f'),t=+v('t');if(!m||!f)return '<div class="hint">Total marks daalein.</div>';let need=(t/100)*(m+f)-o;let pct=need/f*100;let msg=need<=0?'Aap already target par ho! 🎉':pct>100?'Sirf marks se target mushkil — grace/extra dekhein.':'Itne marks laao to target poora.';return `<div class="lbl">Baaki exam me chahiye</div><div class="big">${need<=0?'0':Math.ceil(need)} / ${f}</div><div class="rrow"><span>Yaani</span><b>${need<=0?'0':pct.toFixed(1)}%</b></div><div class="hint">${msg}</div>`;}},
{id:'numbase',cat:'Utility',ic:'💻',name:'Number System',desc:'Binary / Hex / Octal / Decimal',fields:`<label class="f">Number</label><input id="a" type="text" value="255"><label class="f">Kis system me hai?</label><select id="b"><option value="10">Decimal (10)</option><option value="2">Binary (2)</option><option value="8">Octal (8)</option><option value="16">Hex (16)</option></select>`,calc:()=>{let s=(v('a')||'').trim(),b=+v('b');let n=parseInt(s,b);if(isNaN(n))return '<div class="hint">Is base ke liye sahi number daalein.</div>';return `<div class="lbl">Decimal</div><div class="big">${n}</div><div class="rrow"><span>Binary</span><b>${n.toString(2)}</b></div><div class="rrow"><span>Octal</span><b>${n.toString(8)}</b></div><div class="rrow"><span>Hex</span><b>${n.toString(16).toUpperCase()}</b></div>`;}},
{id:'roi',cat:'Nivesh',ic:'📈',name:'ROI Calculator',desc:'Kul return % nikaalein',fields:`<div class="row2"><div><label class="f">Lagaya (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"></div><div><label class="f">Mila/value (₹)</label><input id="b" type="number" inputmode="numeric" value="150000"></div></div><label class="f">Kitne saal (optional)</label><input id="y" type="number" inputmode="numeric" value="3">`,calc:()=>{let inv=+v('a'),fin=+v('b'),y=+v('y');if(!inv)return '<div class="hint">Lagaya rakam daalein.</div>';let roi=(fin-inv)/inv*100;let ann=y>0?(Math.pow(fin/inv,1/y)-1)*100:null;return `<div class="lbl">Total ROI</div><div class="big" style="color:${roi>=0?'#0F766E':'#B91C1C'}">${roi.toFixed(1)}%</div><div class="rrow"><span>Profit/Loss</span><b>${RS(fin-inv)}</b></div>${ann!==null?`<div class="rrow"><span>Saalana (CAGR)</span><b>${ann.toFixed(1)}%</b></div>`:''}<div class="hint">ROI = (mila − lagaya) ÷ lagaya. Alag-alag samay ke nivesh ki asli tulna CAGR se hoti.</div>`;}},
{id:'fuelcompare',cat:'Rozana',ic:'⛽',name:'Petrol vs CNG/EV',desc:'Kaunsa sasta — mahine ka farak',fields:`<label class="f">Har mahine kitne km</label><input id="km" type="number" inputmode="numeric" value="1500"><div class="row2"><div><label class="f">A: ₹/litre (ya unit)</label><input id="p1" type="number" inputmode="numeric" value="105"></div><div><label class="f">A: km/litre</label><input id="m1" type="number" inputmode="numeric" value="18"></div></div><div class="row2"><div><label class="f">B: ₹/kg (ya unit)</label><input id="p2" type="number" inputmode="numeric" value="80"></div><div><label class="f">B: km/kg (ya unit)</label><input id="m2" type="number" inputmode="numeric" value="26"></div></div>`,calc:()=>{let km=+v('km'),p1=+v('p1'),m1=+v('m1'),p2=+v('p2'),m2=+v('m2');if(!km||!m1||!m2)return '<div class="hint">Value daalein.</div>';let c1=km/m1*p1,c2=km/m2*p2;let save=Math.abs(c1-c2);let win=c1<c2?'A':'B';return `<div class="lbl">Sasta: Option ${win}</div><div class="big">${RS(save)}/mahina bachat</div><div class="rrow"><span>A ka kharch</span><b>${RS(c1)}</b></div><div class="rrow"><span>B ka kharch</span><b>${RS(c2)}</b></div><div class="rrow"><span>Saal me bachat</span><b>${RS(save*12)}</b></div><div class="hint">Petrol/diesel = ₹/litre, CNG = ₹/kg, EV = ₹/unit. Mileage apni gaadi ka daalein.</div>`;}},

/* ===== NAYE TOOLS (23) ===== */
{id:'carloan',cat:'Loan/Tax',ic:'🚗',name:'Car Loan EMI',desc:'Down payment ke saath car loan EMI',fields:`<div class="row2"><div><label class="f">Car ki keemat (₹)</label><input id="p" type="number" inputmode="numeric" value="800000"></div><div><label class="f">Down payment (₹)</label><input id="d" type="number" inputmode="numeric" value="150000"></div></div><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="9.5" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="5"></div></div>`,calc:()=>{let L=+v('p')-+v('d'),i=+v('r')/12/100,n=+v('y')*12;if(L<=0)return '<div class="hint">Down payment keemat se kam rakhein.</div>';let E=i?L*i*Math.pow(1+i,n)/(Math.pow(1+i,n)-1):L/n;return `<div class="lbl">Monthly EMI</div><div class="big">${RS(E)}</div><div class="rrow"><span>Loan rakam</span><b>${RS(L)}</b></div><div class="rrow"><span>Total byaj</span><b>${RS(E*n-L)}</b></div><div class="rrow"><span>Total bhugtan</span><b>${RS(E*n)}</b></div><div class="hint">Insurance, RTO aur accessories alag se lagte hain — on-road keemat isse zyada hoti hai.</div>`;}},
{id:'bikeloan',cat:'Loan/Tax',ic:'🏍️',name:'Bike Loan EMI',desc:'Bike/scooty loan ki EMI',fields:`<label class="f">Loan rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="90000"><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="11" step="0.1"></div><div><label class="f">Mahine</label><input id="n" type="number" inputmode="numeric" value="36"></div></div>`,calc:()=>{let L=+v('a'),i=+v('r')/12/100,n=+v('n'),E=i?L*i*Math.pow(1+i,n)/(Math.pow(1+i,n)-1):L/n;return `<div class="lbl">Monthly EMI</div><div class="big">${RS(E)}</div><div class="rrow"><span>Total byaj</span><b>${RS(E*n-L)}</b></div><div class="rrow"><span>Total bhugtan</span><b>${RS(E*n)}</b></div>`;}},
{id:'eduloan',cat:'Loan/Tax',ic:'🎓',name:'Education Loan EMI',desc:'Moratorium ke saath padhai ka loan',fields:`<label class="f">Loan rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="800000"><div class="row3"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="10" step="0.1"></div><div><label class="f">Course + 6 mah (saal)</label><input id="m" type="number" inputmode="numeric" value="4"></div><div><label class="f">Wapasi saal</label><input id="y" type="number" inputmode="numeric" value="7"></div></div>`,calc:()=>{let L=+v('a'),i=+v('r')/12/100,mm=+v('m')*12,n=+v('y')*12;let L2=L*Math.pow(1+i,mm);let E=i?L2*i*Math.pow(1+i,n)/(Math.pow(1+i,n)-1):L2/n;return `<div class="lbl">EMI (moratorium ke baad)</div><div class="big">${RS(E)}</div><div class="rrow"><span>Padhai ke baad bakaya</span><b>${RS(L2)}</b></div><div class="rrow"><span>Moratorium ka byaj</span><b>${RS(L2-L)}</b></div><div class="rrow"><span>Total bhugtan</span><b>${RS(E*n)}</b></div><div class="hint">Moratorium me EMI nahi jaati par byaj judta rehta hai. Padhai ke dauraan sirf byaj bharne se kul kharcha kaafi ghat jaata hai.</div>`;}},
{id:'ploan',cat:'Loan/Tax',ic:'💳',name:'Personal Loan EMI',desc:'Processing fee ke saath asli lagat',fields:`<label class="f">Loan rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="300000"><div class="row3"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="14" step="0.1"></div><div><label class="f">Mahine</label><input id="n" type="number" inputmode="numeric" value="36"></div><div><label class="f">Processing %</label><input id="pf" type="number" inputmode="decimal" value="2" step="0.1"></div></div>`,calc:()=>{let L=+v('a'),i=+v('r')/12/100,n=+v('n'),E=i?L*i*Math.pow(1+i,n)/(Math.pow(1+i,n)-1):L/n;let fee=L*+v('pf')/100;return `<div class="lbl">Monthly EMI</div><div class="big">${RS(E)}</div><div class="rrow"><span>Processing fee (+GST)</span><b>${RS(fee*1.18)}</b></div><div class="rrow"><span>Haath me aayega</span><b>${RS(L-fee*1.18)}</b></div><div class="rrow"><span>Total byaj</span><b>${RS(E*n-L)}</b></div>`;}},
{id:'goldloan',cat:'Loan/Tax',ic:'🥇',name:'Gold Loan',desc:'Sone par kitna loan milega',fields:`<div class="row2"><div><label class="f">Sona (gram)</label><input id="g" type="number" inputmode="numeric" value="50"></div><div><label class="f">Bhaav ₹/gram (22K)</label><input id="p" type="number" inputmode="numeric" value="7000"></div></div><div class="row2"><div><label class="f">LTV %</label><input id="l" type="number" inputmode="numeric" value="75"></div><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="9" step="0.1"></div></div>`,calc:()=>{let val=+v('g')*+v('p'),loan=val*+v('l')/100,yr=loan*+v('r')/100;return `<div class="lbl">Anumanit loan</div><div class="big">${RS(loan)}</div><div class="rrow"><span>Sone ki keemat</span><b>${RS(val)}</b></div><div class="rrow"><span>Saal ka byaj</span><b>${RS(yr)}</b></div><div class="rrow"><span>Mahine ka byaj</span><b>${RS(yr/12)}</b></div><div class="hint">RBI ke niyam ke mutabik gold loan me LTV ki ek adhiktam seema hoti hai. Sirf 18-22K sone par hi loan milta hai, hallmark zaroori hai.</div>`;}},
{id:'revemi',cat:'Loan/Tax',ic:'🔍',name:'EMI Se Byaj Dar',desc:'EMI se asli byaj dar pata karein',fields:`<label class="f">Loan rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="200000"><div class="row2"><div><label class="f">EMI (₹)</label><input id="e" type="number" inputmode="numeric" value="6500"></div><div><label class="f">Mahine</label><input id="n" type="number" inputmode="numeric" value="36"></div></div>`,calc:()=>{let L=+v('a'),E=+v('e'),n=+v('n');if(E*n<=L)return '<div class="hint">EMI bahut kam hai — jaanch lein.</div>';let lo=0,hi=1,r=0;for(let k=0;k<80;k++){r=(lo+hi)/2;let p=r?E*(1-Math.pow(1+r,-n))/r:E*n;if(p>L)lo=r;else hi=r;}let ann=r*12*100;return `<div class="lbl">Asli byaj dar (saalana)</div><div class="big">${ann.toFixed(2)}%</div><div class="rrow"><span>Total bhugtan</span><b>${RS(E*n)}</b></div><div class="rrow"><span>Total byaj</span><b>${RS(E*n-L)}</b></div><div class="hint">Dukandaar "flat rate" batate hain jo asli dar se lagbhag aadhi dikhti hai. Ye tool asli reducing-balance dar nikaalta hai.</div>`;}},
{id:'stampduty',cat:'Loan/Tax',ic:'📜',name:'Stamp Duty & Registry',desc:'Zameen/makaan ki registry ka kharcha',fields:`<label class="f">Property value (₹)</label><input id="a" type="number" inputmode="numeric" value="3000000"><div class="row3"><div><label class="f">Stamp duty %</label><input id="s" type="number" inputmode="decimal" value="5" step="0.1"></div><div><label class="f">Registration %</label><input id="g" type="number" inputmode="decimal" value="1" step="0.1"></div><div><label class="f">Wakeel/misc (₹)</label><input id="m" type="number" inputmode="numeric" value="15000"></div></div>`,calc:()=>{let P=+v('a'),sd=P*+v('s')/100,rg=P*+v('g')/100,ms=+v('m');return `<div class="lbl">Kul registry kharcha</div><div class="big">${RS(sd+rg+ms)}</div><div class="rrow"><span>Stamp duty</span><b>${RS(sd)}</b></div><div class="rrow"><span>Registration fee</span><b>${RS(rg)}</b></div><div class="rrow"><span>Wakeel/misc</span><b>${RS(ms)}</b></div><div class="hint">Har rajya me dar alag hai aur kai rajya mahila kharidaar ko chhoot dete hain. Apne rajya ki official registry site par dar confirm karein.</div>`;}},
{id:'apy',cat:'Nivesh',ic:'🧓',name:'Atal Pension (APY)',desc:'APY me kitna jama, kitni pension',fields:`<div class="row2"><div><label class="f">Abhi umar</label><input id="ag" type="number" inputmode="numeric" value="25"></div><div><label class="f">Chahiye pension (₹/mah)</label><select id="p"><option>1000</option><option>2000</option><option selected>3000</option><option>4000</option><option>5000</option></select></div></div>`,calc:()=>{let a=+v('ag'),P=+v('p');if(a<18||a>40)return '<div class="hint">APY 18 se 40 saal ki umar me hi khulta hai.</div>';let n=(60-a)*12,r=0.08/12;let fv=P*170;let m=fv*r/(Math.pow(1+r,n)-1);return `<div class="lbl">Anumanit mahine ka contribution</div><div class="big">${RS(m)}</div><div class="rrow"><span>Kitne saal jama</span><b>${60-a} saal</b></div><div class="rrow"><span>60 par pension</span><b>₹${P}/mahina</b></div><div class="rrow"><span>Nominee ko corpus</span><b>${RS(fv)}</b></div><div class="hint">Ye anuman hai. Asli contribution APY ki official chart se tay hota hai — bank ya official site par confirm karein.</div>`;}},
{id:'vpf',cat:'Nivesh',ic:'🏦',name:'VPF Calculator',desc:'PF me extra jama par corpus',fields:`<label class="f">Basic+DA (₹/mahina)</label><input id="b" type="number" inputmode="numeric" value="40000"><div class="row3"><div><label class="f">VPF % (extra)</label><input id="p" type="number" inputmode="decimal" value="10" step="0.5"></div><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="8.25" step="0.05"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="20"></div></div>`,calc:()=>{let B=+v('b'),vp=B*+v('p')/100,ep=B*0.12,tot=vp+ep,r=+v('r')/12/100,n=+v('y')*12;let fv=r?tot*((Math.pow(1+r,n)-1)/r)*(1+r):tot*n;let onlyE=r?ep*((Math.pow(1+r,n)-1)/r)*(1+r):ep*n;return `<div class="lbl">Kul corpus (EPF + VPF)</div><div class="big">${RS(fv)}</div><div class="rrow"><span>Sirf EPF hota to</span><b>${RS(onlyE)}</b></div><div class="rrow"><span>VPF se extra</span><b>${RS(fv-onlyE)}</b></div><div class="rrow"><span>Mahine ka VPF</span><b>${RS(vp)}</b></div><div class="hint">VPF me aap apna hissa 12% se oopar badha sakte hain. Company ka hissa nahi badhta. Byaj dar EPF jaisi hi milti hai.</div>`;}},
{id:'mssc',cat:'Nivesh',ic:'👩',name:'Mahila Samman Bachat',desc:'MSSC yojana ka maturity',fields:`<label class="f">Jama rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="200000"><label class="f">Byaj % (abhi ka)</label><input id="r" type="number" inputmode="decimal" value="7.5" step="0.1">`,calc:()=>{let P=+v('a'),r=+v('r')/400;let A=P*Math.pow(1+r,8);return `<div class="lbl">2 saal baad maturity</div><div class="big">${RS(A)}</div><div class="rrow"><span>Jama</span><b>${RS(P)}</b></div><div class="rrow"><span>Byaj</span><b>${RS(A-P)}</b></div><div class="hint">MSSC 2 saal ki yojana hai, quarterly compounding ke saath. Adhiktam jama ki seema hoti hai — post office par confirm karein.</div>`;}},
{id:'advtax',cat:'Loan/Tax',ic:'📆',name:'Advance Tax Kist',desc:'Char kist me kitna bharna hai',fields:`<label class="f">Saal ka anumanit tax (₹)</label><input id="t" type="number" inputmode="numeric" value="120000"><label class="f">Ab tak bhara/TDS (₹)</label><input id="p" type="number" inputmode="numeric" value="20000">`,calc:()=>{let T=+v('t'),paid=+v('p'),net=Math.max(T-paid,0);return `<div class="lbl">Bacha hua tax</div><div class="big">${RS(net)}</div><div class="rrow"><span>15 June tak (15%)</span><b>${RS(T*0.15)}</b></div><div class="rrow"><span>15 Sept tak (45%)</span><b>${RS(T*0.45)}</b></div><div class="rrow"><span>15 Dec tak (75%)</span><b>${RS(T*0.75)}</b></div><div class="rrow"><span>15 March tak (100%)</span><b>${RS(T)}</b></div><div class="hint">Ye cumulative hain — yaani Sept tak kul 45% jama hona chahiye. ₹10,000 se zyada tax bane to advance tax lagta hai. Taaza niyam incometax.gov.in par dekhein.</div>`;}},
{id:'capgain',cat:'Loan/Tax',ic:'📊',name:'Capital Gain (Share)',desc:'Share bechne par gain ka hisaab',fields:`<div class="row2"><div><label class="f">Kharid keemat (₹)</label><input id="b" type="number" inputmode="numeric" value="100000"></div><div><label class="f">Bech keemat (₹)</label><input id="s" type="number" inputmode="numeric" value="180000"></div></div><label class="f">Kitne mahine rakha</label><input id="m" type="number" inputmode="numeric" value="18">`,calc:()=>{let b=+v('b'),s=+v('s'),m=+v('m'),g=s-b;let lt=m>12;return `<div class="lbl">${lt?'Long-term':'Short-term'} capital gain</div><div class="big">${RS(g)}</div><div class="rrow"><span>Kism</span><b>${lt?'LTCG (12 mahine se zyada)':'STCG (12 mahine se kam)'}</b></div><div class="rrow"><span>Growth</span><b>${b?((g/b)*100).toFixed(1)+'%':'-'}</b></div><div class="hint">Listed share/equity fund me 12 mahine ki seema hoti hai. LTCG me ek saalana chhoot bhi milti hai. Tax ki dar samay-samay par badalti hai — filing se pehle incometax.gov.in par confirm karein. ${DISC}</div>`;}},
{id:'hravshl',cat:'Loan/Tax',ic:'⚖️',name:'HRA vs Home Loan',desc:'Kiraya ya EMI — kaunsa sasta',fields:`<div class="row2"><div><label class="f">Mahine ka kiraya (₹)</label><input id="k" type="number" inputmode="numeric" value="18000"></div><div><label class="f">Sambhavit EMI (₹)</label><input id="e" type="number" inputmode="numeric" value="32000"></div></div><div class="row2"><div><label class="f">Maintenance+tax (₹/mah)</label><input id="m" type="number" inputmode="numeric" value="3000"></div><div><label class="f">Down payment (₹)</label><input id="d" type="number" inputmode="numeric" value="800000"></div></div>`,calc:()=>{let k=+v('k'),e=+v('e'),m=+v('m'),d=+v('d');let own=e+m,rent=k;let opp=d*0.08/12;return `<div class="lbl">Mahine ka farak</div><div class="big">${RS(own-rent)}</div><div class="rrow"><span>Ghar ka kul kharcha</span><b>${RS(own)}</b></div><div class="rrow"><span>Kiraya</span><b>${RS(rent)}</b></div><div class="rrow"><span>Down payment ka mauka-lagat</span><b>${RS(opp)}/mah</b></div><div class="hint">Sirf paisa hi sab kuch nahi — apna ghar suraksha aur mann ki shanti deta hai, kiraya lachak. Property ki keemat badhne ka faayda ismein nahi juda hai.</div>`;}},
{id:'nali',cat:'Converter',ic:'🌾',name:'Nali–Mutthi (Uttarakhand)',desc:'Pahadi zameen ka naap badlein',fields:`<label class="f">Value</label><input id="a" type="number" inputmode="numeric" value="1"><div class="row2"><div><label class="f">From</label><select id="f"><option value="2160">nali</option><option value="108">mutthi</option><option value="1">sq ft</option><option value="10.7639">sq m</option><option value="43560">acre</option><option value="107639">hectare</option><option value="2160">bisi(=nali)</option></select></div><div><label class="f">To</label><select id="t"><option value="1">sq ft</option><option value="2160">nali</option><option value="108">mutthi</option><option value="10.7639">sq m</option><option value="43560">acre</option><option value="107639">hectare</option></select></div></div>`,calc:()=>{let a=+v('a'),sf=a*+v('f'),out=sf/+v('t');let fn=document.getElementById('f').selectedOptions[0].text,tn=document.getElementById('t').selectedOptions[0].text;return `<div class="lbl">${a} ${fn} =</div><div class="big">${out.toLocaleString('en-IN',{maximumFractionDigits:4})}</div><div class="rrow"><span>Unit</span><b>${tn}</b></div><div class="hint">Uttarakhand me 1 nali = 16 mutthi = lagbhag 2,160 sq ft (240 sq gaz). Ye naap jagah-jagah thoda badalta hai — patwari ya khatauni se confirm karein.</div>`;}},
{id:'hectare',cat:'Converter',ic:'🗺️',name:'Hectare–Bigha–Acre',desc:'Khet ke bade naap badlein',fields:`<label class="f">Value</label><input id="a" type="number" inputmode="numeric" value="1"><div class="row2"><div><label class="f">From</label><select id="f"><option value="107639">hectare</option><option value="43560">acre</option><option value="27000">bigha (~27000 sqft)</option><option value="1">sq ft</option><option value="10.7639">sq m</option><option value="1350">biswa (~1/20 bigha)</option></select></div><div><label class="f">To</label><select id="t"><option value="43560">acre</option><option value="107639">hectare</option><option value="27000">bigha (~27000 sqft)</option><option value="1">sq ft</option><option value="10.7639">sq m</option><option value="1350">biswa</option></select></div></div>`,calc:()=>{let a=+v('a'),sf=a*+v('f'),out=sf/+v('t');let fn=document.getElementById('f').selectedOptions[0].text,tn=document.getElementById('t').selectedOptions[0].text;return `<div class="lbl">${a} ${fn} =</div><div class="big">${out.toLocaleString('en-IN',{maximumFractionDigits:4})}</div><div class="rrow"><span>Unit</span><b>${tn}</b></div><div class="hint">Bigha har rajya me alag hota hai — UP, Uttarakhand, Bihar, MP aur Rajasthan sab me farak hai. Yahan ~27,000 sqft maana gaya hai.</div>`;}},
{id:'fasal',cat:'Rozana',ic:'🌱',name:'Fasal Munafa',desc:'Kheti ka laagat aur munafa',fields:`<div class="row2"><div><label class="f">Rakba (nali/bigha)</label><input id="r" type="number" inputmode="numeric" value="10"></div><div><label class="f">Upaj per unit (kg)</label><input id="u" type="number" inputmode="numeric" value="120"></div></div><div class="row2"><div><label class="f">Bhaav (₹/kg)</label><input id="b" type="number" inputmode="numeric" value="22"></div><div><label class="f">Kul laagat (₹)</label><input id="l" type="number" inputmode="numeric" value="18000"></div></div>`,calc:()=>{let R=+v('r'),U=+v('u'),B=+v('b'),L=+v('l');let kg=R*U,aay=kg*B,mun=aay-L;return `<div class="lbl">Anumanit munafa</div><div class="big">${RS(mun)}</div><div class="rrow"><span>Kul upaj</span><b>${kg.toLocaleString('en-IN')} kg</b></div><div class="rrow"><span>Kul aay</span><b>${RS(aay)}</b></div><div class="rrow"><span>Kul laagat</span><b>${RS(L)}</b></div><div class="rrow"><span>Per unit munafa</span><b>${R?RS(mun/R):'-'}</b></div><div class="hint">Laagat me beej, khaad, mazdoori, sinchai aur mandi tak le jaane ka kharcha jodna na bhoolein.</div>`;}},
{id:'milkrate',cat:'Rozana',ic:'🥛',name:'Doodh Rate (Fat/SNF)',desc:'Fat aur SNF se doodh ka daam',fields:`<div class="row2"><div><label class="f">Doodh (litre)</label><input id="l" type="number" inputmode="numeric" value="10"></div><div><label class="f">Fat %</label><input id="f" type="number" inputmode="decimal" value="6.5" step="0.1"></div></div><div class="row2"><div><label class="f">SNF %</label><input id="s" type="number" inputmode="decimal" value="8.5" step="0.1"></div><div><label class="f">Rate/kg fat (₹)</label><input id="r" type="number" inputmode="numeric" value="600"></div></div>`,calc:()=>{let L=+v('l'),F=+v('f'),S=+v('s'),R=+v('r');let perL=(F+S/3)*R/100;let tot=perL*L;return `<div class="lbl">Kul rakam</div><div class="big">${RS(tot)}</div><div class="rrow"><span>Per litre</span><b>${RS(perL)}</b></div><div class="rrow"><span>Fat + SNF/3</span><b>${(F+S/3).toFixed(2)}</b></div><div class="hint">Ye "Fat + SNF/3" wala aam formula hai. Har dairy ka apna chart hota hai — apni society ka rate chart zaroor dekhein.</div>`;}},
{id:'concrete',cat:'Rozana',ic:'🧱',name:'Cement Sand Bajri',desc:'Concrete ke liye saman ka hisaab',fields:`<div class="row3"><div><label class="f">Lambai (ft)</label><input id="l" type="number" inputmode="numeric" value="10"></div><div><label class="f">Chaudai (ft)</label><input id="w" type="number" inputmode="numeric" value="10"></div><div><label class="f">Motai (inch)</label><input id="t" type="number" inputmode="numeric" value="4"></div></div><label class="f">Grade</label><select id="g"><option value="5.5">M15 (1:2:4)</option><option value="5.5" selected>M20 (1:1.5:3)</option><option value="4.5">M25 (1:1:2)</option></select>`,calc:()=>{let vol=+v('l')*+v('w')*(+v('t')/12);let wet=vol*1.54;let g=v('g');let parts=g==='4.5'?[1,1,2]:(g==='5.5'?[1,1.5,3]:[1,2,4]);let sum=parts[0]+parts[1]+parts[2];let cem=wet*parts[0]/sum,snd=wet*parts[1]/sum,agg=wet*parts[2]/sum;let bags=cem/1.226;return `<div class="lbl">Cement ki bori (50kg)</div><div class="big">${Math.ceil(bags)}</div><div class="rrow"><span>Wet volume</span><b>${vol.toFixed(1)} cu ft</b></div><div class="rrow"><span>Baalu (sand)</span><b>${snd.toFixed(1)} cu ft</b></div><div class="rrow"><span>Bajri (aggregate)</span><b>${agg.toFixed(1)} cu ft</b></div><div class="hint">Ye anuman hai — 54% dry volume aur aam ratio par. Asli zaroorat mistri aur site ke hisaab se thodi badal sakti hai.</div>`;}},
{id:'paint',cat:'Rozana',ic:'🎨',name:'Paint Ka Hisaab',desc:'Kamre me kitna paint lagega',fields:`<div class="row3"><div><label class="f">Lambai (ft)</label><input id="l" type="number" inputmode="numeric" value="12"></div><div><label class="f">Chaudai (ft)</label><input id="w" type="number" inputmode="numeric" value="10"></div><div><label class="f">Oonchai (ft)</label><input id="h" type="number" inputmode="numeric" value="10"></div></div><div class="row2"><div><label class="f">Coat</label><input id="c" type="number" inputmode="numeric" value="2"></div><div><label class="f">Coverage (sqft/litre)</label><input id="cv" type="number" inputmode="numeric" value="120"></div></div>`,calc:()=>{let L=+v('l'),W=+v('w'),H=+v('h');let wall=2*(L+W)*H,ceil=L*W;let area=(wall+ceil)*0.9;let lit=area*+v('c')/+v('cv');return `<div class="lbl">Paint chahiye</div><div class="big">${lit.toFixed(1)} litre</div><div class="rrow"><span>Deewar ka area</span><b>${wall.toFixed(0)} sq ft</b></div><div class="rrow"><span>Chhat ka area</span><b>${ceil.toFixed(0)} sq ft</b></div><div class="rrow"><span>Kul (darwaza-khidki ghata kar)</span><b>${area.toFixed(0)} sq ft</b></div><div class="hint">Darwaza aur khidki ke liye 10% apne aap ghata diya gaya hai. Primer aur putty alag se lagti hai.</div>`;}},
{id:'tile',cat:'Rozana',ic:'⬜',name:'Tile Ka Hisaab',desc:'Kitni tile aur kitna kharcha',fields:`<div class="row2"><div><label class="f">Room lambai (ft)</label><input id="l" type="number" inputmode="numeric" value="12"></div><div><label class="f">Room chaudai (ft)</label><input id="w" type="number" inputmode="numeric" value="10"></div></div><div class="row3"><div><label class="f">Tile lambai (inch)</label><input id="tl" type="number" inputmode="numeric" value="24"></div><div><label class="f">Tile chaudai (inch)</label><input id="tw" type="number" inputmode="numeric" value="24"></div><div><label class="f">Rate ₹/tile</label><input id="r" type="number" inputmode="numeric" value="90"></div></div>`,calc:()=>{let area=+v('l')*+v('w');let ta=(+v('tl')/12)*(+v('tw')/12);if(ta<=0)return '<div class="hint">Tile ka naap bharein.</div>';let n=Math.ceil(area/ta*1.1);return `<div class="lbl">Tile chahiye (10% wastage ke saath)</div><div class="big">${n}</div><div class="rrow"><span>Room ka area</span><b>${area.toFixed(0)} sq ft</b></div><div class="rrow"><span>Ek tile ka area</span><b>${ta.toFixed(2)} sq ft</b></div><div class="rrow"><span>Anumanit kharcha</span><b>${RS(n*+v('r'))}</b></div><div class="hint">Katai aur toot-phoot ke liye 10% extra joda gaya hai. Design wali tile me 15% rakhna behtar hai. Adhesive aur mazdoori alag.</div>`;}},
{id:'brick',cat:'Rozana',ic:'🧱',name:'Eent Ka Hisaab',desc:'Deewar me kitni eent lagegi',fields:`<div class="row3"><div><label class="f">Lambai (ft)</label><input id="l" type="number" inputmode="numeric" value="20"></div><div><label class="f">Oonchai (ft)</label><input id="h" type="number" inputmode="numeric" value="10"></div><div><label class="f">Motai</label><select id="t"><option value="0.375">4.5 inch</option><option value="0.75" selected>9 inch</option><option value="1.125">13.5 inch</option></select></div></div><label class="f">Rate ₹/eent</label><input id="r" type="number" inputmode="numeric" value="9">`,calc:()=>{let vol=+v('l')*+v('h')*+v('t');let n=Math.ceil(vol*13.5*1.05);return `<div class="lbl">Eent chahiye</div><div class="big">${n.toLocaleString('en-IN')}</div><div class="rrow"><span>Deewar ka volume</span><b>${vol.toFixed(1)} cu ft</b></div><div class="rrow"><span>Anumanit kharcha</span><b>${RS(n*+v('r'))}</b></div><div class="hint">Aam bharatiya eent (9"×4.5"×3") aur mortar ke saath lagbhag 13.5 eent per cubic foot maani gayi hai, 5% toot-phoot ke saath.</div>`;}},
{id:'typing',cat:'Rozana',ic:'⌨️',name:'Typing Speed Test',desc:'Apni typing speed jaanchein',fields:`<label class="f">Kitne shabd type kiye</label><input id="w" type="number" inputmode="numeric" value="200"><div class="row2"><div><label class="f">Kitne minute lage</label><input id="m" type="number" inputmode="decimal" value="5" step="0.1"></div><div><label class="f">Kitni galtiyan</label><input id="e" type="number" inputmode="numeric" value="6"></div></div>`,calc:()=>{let W=+v('w'),M=+v('m'),E=+v('e');if(M<=0)return '<div class="hint">Minute bharein.</div>';let gross=W/M,net=(W-E)/M;let acc=W?((W-E)/W*100):0;return `<div class="lbl">Net speed</div><div class="big">${net.toFixed(1)} WPM</div><div class="rrow"><span>Gross speed</span><b>${gross.toFixed(1)} WPM</b></div><div class="rrow"><span>Sahi %</span><b>${acc.toFixed(1)}%</b></div><div class="hint">Sarkari naukri ke kai exam me 25-35 WPM maanga jaata hai. 40+ WPM achha aur 60+ WPM bahut achha maana jaata hai.</div>`;}},
{id:'rentreceipt',cat:'Rozana',ic:'🧾',name:'Rent Receipt Hisaab',desc:'Saal ka kiraya aur receipt ka hisaab',fields:`<div class="row2"><div><label class="f">Mahine ka kiraya (₹)</label><input id="k" type="number" inputmode="numeric" value="15000"></div><div><label class="f">Kitne mahine</label><input id="m" type="number" inputmode="numeric" value="12"></div></div>`,calc:()=>{let k=+v('k'),m=+v('m'),tot=k*m;let stamp=k>3000;return `<div class="lbl">Saal ka kul kiraya</div><div class="big">${RS(tot)}</div><div class="rrow"><span>Har receipt par</span><b>${RS(k)}</b></div><div class="rrow"><span>Kitni receipt</span><b>${m}</b></div><div class="rrow"><span>Revenue stamp</span><b>${stamp?'Haan (₹3,000+ par)':'Zaroori nahi'}</b></div><div class="hint">HRA claim ke liye receipt par makaan maalik ka naam, pata aur dastakhat chahiye. Saal me ₹1 lakh se zyada kiraya hone par makaan maalik ka PAN bhi dena hota hai.</div>`;}},
{id:'bo5',cat:'Utility',ic:'🎯',name:"CBSE Best of 5 Calculator",desc:"CBSE 6 me se best 5 %",pop:0,fields:`<div class="row3"><div><label class="f">Subject 1</label><input id="s1" type="number" inputmode="numeric" value="88"></div><div><label class="f">Subject 2</label><input id="s2" type="number" inputmode="numeric" value="76"></div><div><label class="f">Subject 3</label><input id="s3" type="number" inputmode="numeric" value="91"></div></div><div class="row3"><div><label class="f">Subject 4</label><input id="s4" type="number" inputmode="numeric" value="82"></div><div><label class="f">Subject 5</label><input id="s5" type="number" inputmode="numeric" value="69"></div><div><label class="f">Subject 6</label><input id="s6" type="number" inputmode="numeric" value="94"></div></div><label class="f">Har subject kitne me se (max)</label><input id="mx" type="number" inputmode="numeric" value="100">`,calc:()=>{var arr=[+v('s1'),+v('s2'),+v('s3'),+v('s4'),+v('s5'),+v('s6')].filter(function(x){return !isNaN(x);});
  var mx=+v('mx')||100;
  if(arr.length<5)return '<div class="hint">Kam se kam 5 subject ke marks daalein.</div>';
  var sorted=arr.slice().sort(function(a,b){return b-a;});
  var top5=sorted.slice(0,5);
  var dropped=sorted.length>5?sorted[5]:null;
  var sum=top5.reduce(function(a,b){return a+b;},0);
  var pct=sum/(5*mx)*100;
  return '<div class="lbl">Best of 5 Percentage</div><div class="big">'+pct.toFixed(2)+'%</div>'
   +'<div class="rrow"><span>Top 5 ka jod</span><b>'+sum+' / '+(5*mx)+'</b></div>'
   +(dropped!==null?'<div class="rrow"><span>Chhoda gaya (sabse kam)</span><b>'+dropped+'</b></div>':'')
   +'<div class="hint">Sabse kam number wala subject apne aap hataya gaya. College ka apna niyam alag ho sakta hai.</div>';}},
{id:'s80c',cat:'Loan/Tax',ic:'💰',name:"Section 80C Saving Calculator",desc:"80C tax bachat (\u20b91.5L)",pop:0,fields:`<label class="f">EPF + VPF (saal ka, ₹)</label><input id="epf" type="number" inputmode="numeric" value="30000"><div class="row2"><div><label class="f">PPF (₹)</label><input id="ppf" type="number" inputmode="numeric" value="50000"></div><div><label class="f">ELSS / LIC (₹)</label><input id="elss" type="number" inputmode="numeric" value="40000"></div></div><div class="row2"><div><label class="f">Bachche ki tuition fee (₹)</label><input id="tf" type="number" inputmode="numeric" value="20000"></div><div><label class="f">Home loan principal (₹)</label><input id="hl" type="number" inputmode="numeric" value="0"></div></div><label class="f">Aapka tax slab %</label><select id="slab"><option value="5">5%</option><option value="20" selected>20%</option><option value="30">30%</option></select>`,calc:()=>{var total=(+v('epf')||0)+(+v('ppf')||0)+(+v('elss')||0)+(+v('tf')||0)+(+v('hl')||0);
  var allowed=Math.min(total,150000);
  var slab=+v('slab');
  var saving=allowed*slab/100;
  var left=Math.max(0,150000-total);
  return '<div class="lbl">Tax bachat (approx)</div><div class="big">'+RS(saving)+'</div>'
   +'<div class="rrow"><span>Kul 80C nivesh</span><b>'+RS(total)+'</b></div>'
   +'<div class="rrow"><span>Maanya chhoot</span><b>'+RS(allowed)+' / ₹1,50,000</b></div>'
   +(left>0?'<div class="rrow"><span>Aur daal sakte hain</span><b>'+RS(left)+'</b></div>':'<div class="rrow"><span>Seema</span><b>Poori bhar gayi ✓</b></div>')
   +'<div class="hint">Sirf old regime me. NPS ka ₹50,000 (80CCD-1B) isse alag milta hai.</div>';}},
{id:'deprec',cat:'Loan/Tax',ic:'📉',name:"Depreciation Calculator",desc:"SLM/WDV depreciation",pop:0,fields:`<label class="f">Asset ki keemat (₹)</label><input id="c" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Depreciation rate %</label><input id="r" type="number" inputmode="decimal" value="15" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="5"></div></div><label class="f">Method</label><select id="m"><option value="wdv">WDV (Written Down Value)</option><option value="slm">SLM (Straight Line)</option></select>`,calc:()=>{var c=+v('c'),r=+v('r')/100,y=+v('y'),m=v('m');
  if(!c||!r||!y)return '<div class="hint">Sab value daalein.</div>';
  var rows='',val=c,totalDep=0;
  for(var i=1;i<=y;i++){
    var dep=m==='slm'? c*r : val*r;
    val=Math.max(0,val-dep); totalDep+=dep;
    rows+='<div class="rrow"><span>Saal '+i+' depreciation</span><b>'+RS(dep)+'</b></div>';
  }
  return '<div class="lbl">'+y+' saal baad book value</div><div class="big">'+RS(val)+'</div>'
   +'<div class="rrow"><span>Kul depreciation</span><b>'+RS(totalDep)+'</b></div>'
   +rows
   +'<div class="hint">Method: '+(m==='slm'?'Straight Line':'Written Down Value')+'. Rate official list se confirm karein.</div>';}},
{id:'zakat',cat:'Nivesh',ic:'🕌',name:"Zakat Calculator",desc:"Zakat 2.5% ka hisaab",pop:0,fields:`<label class="f">Cash + bank balance (₹)</label><input id="cash" type="number" inputmode="numeric" value="200000"><div class="row2"><div><label class="f">Sone ki keemat (₹)</label><input id="gold" type="number" inputmode="numeric" value="150000"></div><div><label class="f">Chaandi + doosri (₹)</label><input id="silver" type="number" inputmode="numeric" value="0"></div></div><div class="row2"><div><label class="f">Nivesh / business stock (₹)</label><input id="inv" type="number" inputmode="numeric" value="50000"></div><div><label class="f">Dena wala karz (₹)</label><input id="debt" type="number" inputmode="numeric" value="30000"></div></div>`,calc:()=>{var assets=(+v('cash')||0)+(+v('gold')||0)+(+v('silver')||0)+(+v('inv')||0);
  var debt=+v('debt')||0;
  var net=Math.max(0,assets-debt);
  var zakat=net*0.025;
  return '<div class="lbl">Dena wali Zakat (2.5%)</div><div class="big">'+RS(zakat)+'</div>'
   +'<div class="rrow"><span>Kul zakat-yogya sampatti</span><b>'+RS(assets)+'</b></div>'
   +'<div class="rrow"><span>Karz ghata kar</span><b>'+RS(net)+'</b></div>'
   +'<div class="hint">Yaad rahe: Zakat tab hi banti hai jab ye rakam nisab (sona/chaandi ki nyoontam keemat) se upar ho. Nisab aaj ke bhaav se confirm karein.</div>';}},
{id:'sqftsqm',cat:'Converter',ic:'📐',name:"Sq Ft to Sq Meter Converter",desc:"Sq ft \u2194 sq meter",pop:0,fields:`<label class="f">Value</label><input id="a" type="number" inputmode="numeric" value="1000"><label class="f">Kis unit me hai?</label><select id="f"><option value="0.092903">Square Feet (sq ft)</option><option value="1">Square Meter (sq m)</option><option value="0.836127">Square Yard (gaj)</option><option value="0.00064516">Square Inch</option></select>`,calc:()=>{var a=+v('a'),f=+v('f');
  if(isNaN(a))return '<div class="hint">Value daalein.</div>';
  var sqm=a*f;
  var sqft=sqm/0.092903, gaj=sqm/0.836127, sqin=sqm/0.00064516;
  return '<div class="lbl">Square Meter</div><div class="big">'+sqm.toLocaleString('en-IN',{maximumFractionDigits:3})+'</div>'
   +'<div class="rrow"><span>Square Feet</span><b>'+sqft.toLocaleString('en-IN',{maximumFractionDigits:2})+'</b></div>'
   +'<div class="rrow"><span>Square Yard (gaj)</span><b>'+gaj.toLocaleString('en-IN',{maximumFractionDigits:2})+'</b></div>'
   +'<div class="rrow"><span>Square Inch</span><b>'+sqin.toLocaleString('en-IN',{maximumFractionDigits:0})+'</b></div>';}},
{id:'timedur',cat:'Utility',ic:'⏱️',name:"Time Duration Calculator",desc:"Do samay ke beech ghante",pop:0,fields:`<div class="row2"><div><label class="f">Start time</label><input id="s" type="time" value="09:30"></div><div><label class="f">End time</label><input id="e" type="time" value="18:15"></div></div><label class="f">Break/lunch (minute)</label><input id="b" type="number" inputmode="numeric" value="30">`,calc:()=>{var s=v('s'),e=v('e'),b=+v('b')||0;
  if(!s||!e)return '<div class="hint">Start aur end time daalein.</div>';
  var sp=s.split(':'),ep=e.split(':');
  var sm=(+sp[0])*60+(+sp[1]), em=(+ep[0])*60+(+ep[1]);
  var diff=em-sm; if(diff<0)diff+=1440;
  diff-=b; if(diff<0)diff=0;
  var h=Math.floor(diff/60), m=diff%60;
  return '<div class="lbl">Kul avadhi</div><div class="big">'+h+' ghante '+m+' min</div>'
   +'<div class="rrow"><span>Sirf minute me</span><b>'+diff+' min</b></div>'
   +'<div class="rrow"><span>Decimal ghante</span><b>'+(diff/60).toFixed(2)+'</b></div>'
   +(b>0?'<div class="rrow"><span>Break ghata gaya</span><b>'+b+' min</b></div>':'')
   +'<div class="hint">Aadhi raat paar hone par agli subah maan kar ginte hain.</div>';}},
{id:'tdee',cat:'Sehat',ic:'🔥',name:"TDEE Calculator",desc:"Roz ki calorie zaroorat",pop:0,fields:`<div class="row2"><div><label class="f">Umar</label><input id="age" type="number" inputmode="numeric" value="30"></div><div><label class="f">Ling</label><select id="sex"><option value="m">Purush</option><option value="f">Mahila</option></select></div></div><div class="row2"><div><label class="f">Weight (kg)</label><input id="w" type="number" inputmode="numeric" value="70"></div><div><label class="f">Height (cm)</label><input id="h" type="number" inputmode="numeric" value="170"></div></div><label class="f">Activity level</label><select id="act"><option value="1.2">Bahut kam (desk job, koi exercise nahi)</option><option value="1.375" selected>Halka (hafte 1-3 din exercise)</option><option value="1.55">Madhyam (hafte 3-5 din)</option><option value="1.725">Zyada (hafte 6-7 din)</option><option value="1.9">Bahut zyada (athlete/labour)</option></select>`,calc:()=>{var age=+v('age'),w=+v('w'),h=+v('h'),act=+v('act'),sex=v('sex');
  if(!age||!w||!h)return '<div class="hint">Sab value daalein.</div>';
  var bmr=10*w+6.25*h-5*age+(sex==='m'?5:-161);
  var tdee=bmr*act;
  return '<div class="lbl">Roz ki zaroorat (maintenance)</div><div class="big">'+Math.round(tdee).toLocaleString('en-IN')+' cal</div>'
   +'<div class="rrow"><span>BMR (aaram ki calorie)</span><b>'+Math.round(bmr).toLocaleString('en-IN')+' cal</b></div>'
   +'<div class="rrow"><span>Vazan ghatane ke liye</span><b>'+Math.round(tdee-500).toLocaleString('en-IN')+' cal</b></div>'
   +'<div class="rrow"><span>Vazan badhane ke liye</span><b>'+Math.round(tdee+400).toLocaleString('en-IN')+' cal</b></div>'
   +'<div class="hint">Mifflin-St Jeor formula. Ye anuman hai — apna vazan 2-3 hafte track karke adjust karein. Doctor ki salah ki jagah nahi.</div>';}},
{id:'macro',cat:'Sehat',ic:'🍗',name:"Macro Calculator",desc:"Protein/carb/fat split",pop:0,fields:`<label class="f">Roz ki calorie (TDEE se)</label><input id="cal" type="number" inputmode="numeric" value="2200"><label class="f">Lakshya</label><select id="goal"><option value="loss">Vazan ghatana (zyada protein)</option><option value="maint" selected>Vazan banaye rakhna</option><option value="gain">Muscle badhana</option></select><label class="f">Weight (kg) — protein ke liye</label><input id="w" type="number" inputmode="numeric" value="70">`,calc:()=>{var cal=+v('cal'),goal=v('goal'),w=+v('w');
  if(!cal)return '<div class="hint">Calorie daalein.</div>';
  var p,c,f;
  if(goal==='loss'){p=0.40;c=0.30;f=0.30;}
  else if(goal==='gain'){p=0.30;c=0.45;f=0.25;}
  else{p=0.30;c=0.40;f=0.30;}
  var pg=cal*p/4, cg=cal*c/4, fg=cal*f/9;
  var perKg=w?(pg/w).toFixed(1):'-';
  return '<div class="lbl">Roz ka macro target</div>'
   +'<div class="rrow" style="border:none;margin-top:12px"><span>Protein</span><b>'+Math.round(pg)+' g ('+Math.round(p*100)+'%)</b></div>'
   +'<div class="rrow"><span>Carbs</span><b>'+Math.round(cg)+' g ('+Math.round(c*100)+'%)</b></div>'
   +'<div class="rrow"><span>Fat</span><b>'+Math.round(fg)+' g ('+Math.round(f*100)+'%)</b></div>'
   +'<div class="rrow"><span>Protein per kg</span><b>'+perKg+' g/kg</b></div>'
   +'<div class="hint">Calorie per gram: protein/carbs 4, fat 9. Ye anuman hai — dietician ki salah ki jagah nahi.</div>';}},
{id:'sci',cat:'Utility',ic:'🧮',name:"Scientific Calculator",desc:"Trig, log, power",pop:0,fields:`<label class="f">Expression likhein</label><input id="a" type="text" value="2*(3+4)^2" placeholder="jaise: sin(30)+sqrt(16)"><div class="hint" style="margin-top:8px">Istemaal: + &minus; * / ^ ( ) &middot; sin cos tan &middot; log ln &middot; sqrt &middot; pi e &middot; ! (factorial). Angle degree me.</div>`,calc:()=>{var raw=(v('a')||'').trim();
  if(!raw)return '<div class="hint">Expression likhein.</div>';
  try{
    var s=raw.toLowerCase();
    var cleaned=s.replace(/asin|acos|atan|sin|cos|tan|sqrt|log|ln|abs|pi|e|fact/g,'');
    if(/[a-z]/.test(cleaned)) throw 0;
    if(!/^[0-9+\-*/^(). ,!]*$/.test(cleaned)) throw 0;
    var D=Math.PI/180;
    s=s.replace(/\bpi\b/g,'('+Math.PI+')');
    s=s.replace(/\be\b/g,'('+Math.E+')');
    s=s.replace(/asin\(/g,'AS(').replace(/acos\(/g,'AC(').replace(/atan\(/g,'AT(');
    s=s.replace(/sin\(/g,'SIN(').replace(/cos\(/g,'COS(').replace(/tan\(/g,'TAN(');
    s=s.replace(/sqrt\(/g,'SQRT(').replace(/abs\(/g,'ABS(');
    s=s.replace(/\bln\(/g,'LOGE(').replace(/\blog\(/g,'LOG10(');
    s=s.replace(/(\d+(?:\.\d+)?)\s*!/g,'FACT($1)');
    s=s.replace(/\^/g,'**');
    var SIN=function(x){return Math.sin(x*D);},COS=function(x){return Math.cos(x*D);},TAN=function(x){return Math.tan(x*D);};
    var AS=function(x){return Math.asin(x)/D;},AC=function(x){return Math.acos(x)/D;},AT=function(x){return Math.atan(x)/D;};
    var SQRT=Math.sqrt,ABS=Math.abs,LOGE=Math.log,LOG10=Math.log10;
    var FACT=function(n){n=Math.round(n);if(n<0||n>170)return NaN;var r=1;for(var i=2;i<=n;i++)r*=i;return r;};
    var res=Function('SIN','COS','TAN','AS','AC','AT','SQRT','ABS','LOGE','LOG10','FACT','return ('+s+')')(SIN,COS,TAN,AS,AC,AT,SQRT,ABS,LOGE,LOG10,FACT);
    if(res===Infinity||res===-Infinity||isNaN(res)||typeof res!=='number')throw 0;
    if(Math.abs(res)<1e-10)res=0;
    res=Math.round(res*1e10)/1e10;
    return '<div class="lbl">Jawab</div><div class="big">'+res.toLocaleString('en-IN',{maximumFractionDigits:10})+'</div>'
      +'<div class="rrow"><span>Expression</span><b style="word-break:break-all">'+raw+'</b></div>';
  }catch(e){
    return '<div class="hint">Expression samajh nahi aaya. Bracket, chinh aur function (sin, sqrt, log) sahi likhein. Jaise: 2*(3+4)^2</div>';
  }}},
{id:'amort',cat:'Loan/Tax',ic:'📊',name:"Loan Amortization Calculator",desc:"EMI ka byaj/principal breakup",pop:0,fields:`<label class="f">Loan amount (₹)</label><input id="a" type="number" inputmode="numeric" value="2500000"><div class="row2"><div><label class="f">Byaj %</label><input id="r" type="number" inputmode="decimal" value="8.5" step="0.1"></div><div><label class="f">Saal</label><input id="y" type="number" inputmode="numeric" value="20"></div></div>`,calc:()=>{var P=+v('a'),r=+v('r')/12/100,n=+v('y')*12;
  if(!P||!n)return '<div class="hint">Loan aur saal daalein.</div>';
  var E=r? P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1) : P/n;
  var bal=P,rows='',yInt=0,yPrin=0,yr=1;
  for(var i=1;i<=n;i++){
    var intr=bal*r, prin=E-intr; bal-=prin; yInt+=intr; yPrin+=prin;
    if(i%12===0||i===n){
      rows+='<div class="rrow"><span>Saal '+yr+' (byaj / mool)</span><b>'+RS(yInt)+' / '+RS(yPrin)+'</b></div>';
      yInt=0;yPrin=0;yr++;
      if(yr>6&&i<n-12){ rows+='<div class="rrow"><span>...</span><b>...</b></div>'; 
        // jump to last year
        while(i<n-12){var it=bal*r,pr=E-it;bal-=pr;i++;}
        continue;
      }
    }
  }
  return '<div class="lbl">Monthly EMI</div><div class="big">'+RS(E)+'</div>'
   +'<div class="rrow"><span>Total byaj</span><b>'+RS(E*n-P)+'</b></div>'
   +'<div class="rrow"><span>Total bhugtan</span><b>'+RS(E*n)+'</b></div>'
   +rows
   +'<div class="hint">Shuru me byaj zyada, baad me principal zyada. Prepayment shuru me sabse faydemand.</div>';}},
{id:'invtot',cat:'Rozana',ic:'🧾',name:"Invoice Total Calculator",desc:"GST ke saath bill total",pop:0,fields:`<div class="row2"><div><label class="f">Rate (₹/unit)</label><input id="r" type="number" inputmode="numeric" value="500"></div><div><label class="f">Quantity</label><input id="q" type="number" inputmode="numeric" value="10"></div></div><div class="row2"><div><label class="f">Discount %</label><input id="d" type="number" inputmode="decimal" value="10" step="0.1"></div><div><label class="f">GST %</label><select id="g"><option value="0">0%</option><option value="5">5%</option><option value="12">12%</option><option value="18" selected>18%</option><option value="28">28%</option></select></div></div>`,calc:()=>{var r=+v('r'),q=+v('q'),d=+v('d'),g=+v('g');
  if(!r||!q)return '<div class="hint">Rate aur quantity daalein.</div>';
  var base=r*q;
  var disc=base*d/100;
  var taxable=base-disc;
  var gst=taxable*g/100;
  var total=taxable+gst;
  return '<div class="lbl">Invoice total</div><div class="big">'+RS(total)+'</div>'
   +'<div class="rrow"><span>Base ('+q+' &times; '+RS(r)+')</span><b>'+RS(base)+'</b></div>'
   +(d>0?'<div class="rrow"><span>Discount ('+d+'%)</span><b>&minus; '+RS(disc)+'</b></div>':'')
   +'<div class="rrow"><span>Taxable amount</span><b>'+RS(taxable)+'</b></div>'
   +'<div class="rrow"><span>GST ('+g+'%)</span><b>'+RS(gst)+'</b></div>'
   +(g>0?'<div class="rrow"><span>CGST / SGST (same state)</span><b>'+RS(gst/2)+' / '+RS(gst/2)+'</b></div>':'')
   +'<div class="hint">Doosre rajya ke bill me GST "IGST" ke roop me ek saath lagta hai.</div>';}},
{id:'ptax',cat:'Loan/Tax',ic:'🏛️',name:"Professional Tax Calculator",desc:"State professional tax",pop:0,fields:`<label class="f">Monthly salary (₹)</label><input id="s" type="number" inputmode="numeric" value="40000"><label class="f">Rajya (state)</label><select id="st"><option value="mh">Maharashtra</option><option value="ka">Karnataka</option><option value="wb">West Bengal</option><option value="tn">Tamil Nadu</option><option value="gj">Gujarat</option><option value="none">Delhi/UP/Haryana (PT nahi)</option></select>`,calc:()=>{var s=+v('s'),st=v('st');
  if(!s)return '<div class="hint">Salary daalein.</div>';
  var pt=0,note='';
  if(st==='none'){pt=0;note='Is rajya me professional tax nahi lagta.';}
  else if(st==='mh'){ pt = s<=7500?0 : s<=10000?175 : 200; note='Maharashtra: Feb me ₹300 tak, saal me ~₹2,500.'; }
  else if(st==='ka'){ pt = s<25000?0:200; note='Karnataka: ₹25,000+ par ~₹200/mah.'; }
  else if(st==='wb'){ pt = s<=10000?0 : s<=15000?110 : s<=25000?130 : s<=40000?150 : 200; note='West Bengal slab par.'; }
  else if(st==='tn'){ pt = s<=21000?0:200; note='Tamil Nadu: half-yearly slab, ~₹200/mah औसत.'; }
  else if(st==='gj'){ pt = s<12000?0:200; note='Gujarat: ₹12,000+ par ₹200/mah.'; }
  return '<div class="lbl">Anumaanit PT (mahina)</div><div class="big">'+RS(pt)+'</div>'
   +'<div class="rrow"><span>Saal me lagbhag</span><b>'+RS(Math.min(pt*12,2500))+'</b></div>'
   +'<div class="rrow"><span>Adhiktam (saal)</span><b>₹2,500</b></div>'
   +'<div class="hint">'+note+' Taaza slab state website se confirm karein.</div>';}},
{id:'neet',cat:'Utility',ic:'📝',name:"NEET Marks Calculator",desc:"NEET +4/\u22121 score",pop:0,fields:`<div class="row2"><div><label class="f">Sahi answer</label><input id="c" type="number" inputmode="numeric" value="150"></div><div><label class="f">Galat answer</label><input id="w" type="number" inputmode="numeric" value="20"></div></div><label class="f">Kul question (NEET me aksar 180)</label><input id="t" type="number" inputmode="numeric" value="180">`,calc:()=>{var c=+v('c'),w=+v('w'),t=+v('t')||180;
  if(isNaN(c)||isNaN(w))return '<div class="hint">Sahi aur galat answer daalein.</div>';
  var score=c*4-w*1;
  var attempted=c+w;
  var skipped=Math.max(0,t-attempted);
  var maxm=t*4;
  var pct=(score/maxm*100);
  return '<div class="lbl">Anumaanit NEET score</div><div class="big">'+score+' / '+maxm+'</div>'
   +'<div class="rrow"><span>Sahi (&times;4)</span><b>+'+(c*4)+'</b></div>'
   +'<div class="rrow"><span>Galat (&times;&minus;1)</span><b>&minus;'+w+'</b></div>'
   +'<div class="rrow"><span>Chhode gaye</span><b>'+skipped+'</b></div>'
   +'<div class="rrow"><span>Percentage</span><b>'+pct.toFixed(1)+'%</b></div>'
   +'<div class="hint">Official answer key se milaayein. Score ≠ rank — rank har saal badalta hai.</div>';}},
{id:'recipe',cat:'Rozana',ic:'🍲',name:"Recipe Scaler Calculator",desc:"Servings ke hisaab se saman",pop:0,fields:`<div class="row2"><div><label class="f">Recipe kitne logon ki</label><input id="o" type="number" inputmode="numeric" value="4"></div><div><label class="f">Kitne logon ke liye chahiye</label><input id="n" type="number" inputmode="numeric" value="10"></div></div><label class="f">Ek ingredient ka amount (jaise aata gram)</label><input id="a" type="number" inputmode="numeric" value="500">`,calc:()=>{var o=+v('o'),n=+v('n'),a=+v('a');
  if(!o||!n||isNaN(a))return '<div class="hint">Sab value daalein.</div>';
  var ratio=n/o;
  var na=a*ratio;
  return '<div class="lbl">Naya amount</div><div class="big">'+na.toLocaleString('en-IN',{maximumFractionDigits:1})+'</div>'
   +'<div class="rrow"><span>Ratio</span><b>&times; '+ratio.toFixed(2)+'</b></div>'
   +'<div class="rrow"><span>Original ('+o+' log)</span><b>'+a+'</b></div>'
   +'<div class="rrow"><span>Chahiye ('+n+' log)</span><b>'+na.toFixed(1)+'</b></div>'
   +'<div class="hint">Yahi ratio ('+ratio.toFixed(2)+') baaki sab ingredient par lagaiye. Masala swaad se adjust karein.</div>';}},
{id:'fdladder',cat:'Nivesh',ic:'🪜',name:"FD Ladder Calculator",desc:"FD laddering ka hisaab",pop:0,fields:`<label class="f">Total rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="500000"><div class="row2"><div><label class="f">Kitni FD me baantein</label><input id="n" type="number" inputmode="numeric" value="5"></div><div><label class="f">Byaj % (औसत)</label><input id="r" type="number" inputmode="decimal" value="7" step="0.1"></div></div>`,calc:()=>{var A=+v('a'),n=+v('n'),r=+v('r')/100;
  if(!A||!n||!r)return '<div class="hint">Sab value daalein.</div>';
  var per=A/n, rows='', totalMat=0;
  for(var i=1;i<=n;i++){
    var mat=per*Math.pow(1+r/4,4*i); // quarterly compounding
    totalMat+=mat;
    rows+='<div class="rrow"><span>FD '+i+' ('+i+' saal baad)</span><b>'+RS(mat)+'</b></div>';
  }
  return '<div class="lbl">Har FD me daalein</div><div class="big">'+RS(per)+'</div>'
   +'<div class="rrow"><span>Kul maturity (sab FD)</span><b>'+RS(totalMat)+'</b></div>'
   +'<div class="rrow"><span>Kul byaj</span><b>'+RS(totalMat-A)+'</b></div>'
   +rows
   +'<div class="hint">Har saal ek FD khulti hai — liquidity + byaj dono. Byaj taxable hai.</div>';}},
{id:'attend',cat:'Utility',ic:'📅',name:"Attendance Percentage Calculator",desc:"Attendance % (75%)",pop:0,fields:`<div class="row2"><div><label class="f">Attend ki class</label><input id="a" type="number" inputmode="numeric" value="60"></div><div><label class="f">Total class</label><input id="t" type="number" inputmode="numeric" value="80"></div></div><label class="f">Zaroori attendance %</label><input id="r" type="number" inputmode="decimal" value="75" step="0.1">`,calc:()=>{var a=+v('a'),t=+v('t'),r=+v('r');
  if(!t||isNaN(a))return '<div class="hint">Attend ki aur total class daalein.</div>';
  var pct=a/t*100;
  var out='<div class="lbl">Aapki attendance</div><div class="big">'+pct.toFixed(1)+'%</div>'
    +'<div class="rrow"><span>Attend / Total</span><b>'+a+' / '+t+'</b></div>';
  if(pct>=r){
    // how many can bunk
    var bunk=Math.floor((a*100 - r*t)/r);
    out+='<div class="rrow"><span>Aap chhod sakte hain (approx)</span><b>'+Math.max(0,bunk)+' class</b></div>'
      +'<div class="hint">Target ('+r+'%) se upar ho. Utni class tak bunk kar sakte hain jab tak seema na toote.</div>';
  } else {
    var need=Math.ceil((r*t - a*100)/(100 - r));
    out+='<div class="rrow"><span>'+r+'% ke liye chahiye</span><b>'+need+' aur class (lagataar)</b></div>'
      +'<div class="hint">Itni class lagataar attend karein to attendance '+r+'% par pahunch jaayegi.</div>';
  }
  return out;}},
{id:'ratio',cat:'Utility',ic:'➗',name:"Ratio Calculator",desc:"Anupaat simplify/divide",pop:0,fields:`<label class="f">Ratio (A : B)</label><div class="row2"><div><input id="a" type="number" inputmode="numeric" value="8"></div><div><input id="b" type="number" inputmode="numeric" value="12"></div></div><label class="f">Baantne ke liye rakam (optional)</label><input id="amt" type="number" inputmode="numeric" value="5000">`,calc:()=>{var a=+v('a'),b=+v('b'),amt=+v('amt');
  if(!a||!b)return '<div class="hint">Ratio ke dono number daalein.</div>';
  function gcd(x,y){x=Math.abs(x);y=Math.abs(y);while(y){var t=y;y=x%y;x=t;}return x||1;}
  var g=gcd(a,b);
  var sa=a/g, sb=b/g;
  var out='<div class="lbl">Simplified ratio</div><div class="big">'+sa+' : '+sb+'</div>'
    +'<div class="rrow"><span>Original</span><b>'+a+' : '+b+'</b></div>'
    +'<div class="rrow"><span>Decimal (A/B)</span><b>'+(a/b).toFixed(3)+'</b></div>';
  if(amt&&amt>0){
    var tot=a+b;
    out+='<div class="rrow"><span>'+amt.toLocaleString('en-IN')+' ka pehla hissa</span><b>'+RS(amt*a/tot)+'</b></div>'
       +'<div class="rrow"><span>Doosra hissa</span><b>'+RS(amt*b/tot)+'</b></div>';
  }
  return out;}},
{id:'average',cat:'Utility',ic:'📈',name:"Average Calculator",desc:"Mean, median, sum",pop:0,fields:`<label class="f">Number daalein (comma ya space se alag)</label><textarea id="a" rows="4" placeholder="jaise: 85, 90, 78, 92, 88">85, 90, 78, 92, 88</textarea>`,calc:()=>{var raw=(v('a')||'').trim();
  var nums=raw.split(/[\s,]+/).map(function(x){return parseFloat(x);}).filter(function(x){return !isNaN(x);});
  if(nums.length===0)return '<div class="hint">Kuch number daalein (comma ya space se alag).</div>';
  var sum=nums.reduce(function(p,c){return p+c;},0);
  var avg=sum/nums.length;
  var sorted=nums.slice().sort(function(x,y){return x-y;});
  var mid=Math.floor(sorted.length/2);
  var median=sorted.length%2? sorted[mid] : (sorted[mid-1]+sorted[mid])/2;
  return '<div class="lbl">Average (mean)</div><div class="big">'+avg.toLocaleString('en-IN',{maximumFractionDigits:3})+'</div>'
   +'<div class="rrow"><span>Jod (sum)</span><b>'+sum.toLocaleString('en-IN',{maximumFractionDigits:3})+'</b></div>'
   +'<div class="rrow"><span>Kitne number</span><b>'+nums.length+'</b></div>'
   +'<div class="rrow"><span>Median (beech ka)</span><b>'+median.toLocaleString('en-IN',{maximumFractionDigits:3})+'</b></div>'
   +'<div class="rrow"><span>Sabse bada / chhota</span><b>'+sorted[sorted.length-1]+' / '+sorted[0]+'</b></div>';}},
{id:'mileage',cat:'Rozana',ic:'⛽',name:"Mileage Calculator",desc:"Gaadi ka asli km/l",pop:0,fields:`<label class="f">Chali gayi doori (km)</label><input id="km" type="number" inputmode="numeric" value="450"><div class="row2"><div><label class="f">Fuel bhara (litre)</label><input id="l" type="number" inputmode="decimal" value="30" step="0.1"></div><div><label class="f">Fuel rate (₹/litre)</label><input id="r" type="number" inputmode="decimal" value="102" step="0.1"></div></div>`,calc:()=>{var km=+v('km'),l=+v('l'),r=+v('r');
  if(!km||!l)return '<div class="hint">Km aur litre daalein.</div>';
  var mil=km/l;
  var perKm = r? r/mil : 0;
  var out='<div class="lbl">Aapki gaadi ka mileage</div><div class="big">'+mil.toFixed(2)+' km/l</div>'
    +'<div class="rrow"><span>Chali / Bhara</span><b>'+km+' km / '+l+' L</b></div>';
  if(r){ out+='<div class="rrow"><span>Per-km fuel kharch</span><b>'+RS(perKm)+'</b></div>'
    +'<div class="rrow"><span>100 km ka kharch</span><b>'+RS(perKm*100)+'</b></div>'; }
  out+='<div class="hint">Tank-full method sabse sahi. 2-3 baar naap kar ausat lein.</div>';
  return out;}},
{id:'overtime',cat:'Rozana',ic:'⏰',name:"Overtime Pay Calculator",desc:"Extra ghante ki kamai",pop:0,fields:`<label class="f">Hourly rate (₹)</label><input id="hr" type="number" inputmode="numeric" value="150"><div class="row2"><div><label class="f">Overtime ghante</label><input id="ot" type="number" inputmode="numeric" value="12"></div><div><label class="f">OT rate</label><select id="m"><option value="1.5">1.5x (Double time nahi)</option><option value="2">2x (Double)</option><option value="1">1x (Same rate)</option></select></div></div>`,calc:()=>{var hr=+v('hr'),ot=+v('ot'),m=+v('m');
  if(!hr||!ot)return '<div class="hint">Hourly rate aur overtime ghante daalein.</div>';
  var pay=hr*ot*m;
  var normal=hr*ot;
  return '<div class="lbl">Overtime pay (extra)</div><div class="big">'+RS(pay)+'</div>'
   +'<div class="rrow"><span>OT ghante</span><b>'+ot+'</b></div>'
   +'<div class="rrow"><span>Rate (with '+m+'x)</span><b>'+RS(hr*m)+' /ghanta</b></div>'
   +'<div class="rrow"><span>Normal rate hota to</span><b>'+RS(normal)+'</b></div>'
   +'<div class="rrow"><span>Extra (multiplier se)</span><b>'+RS(pay-normal)+'</b></div>'
   +'<div class="hint">Bharat me kai jagah overtime 2x hota hai. Apni company policy confirm karein.</div>';}},
{id:'leaveenc',cat:'Loan/Tax',ic:'🏖️',name:"Leave Encashment Calculator",desc:"Bachi chhutti ka paisa",pop:0,fields:`<label class="f">Bachi leave (din)</label><input id="days" type="number" inputmode="numeric" value="120"><div class="row2"><div><label class="f">Basic + DA (mahina, ₹)</label><input id="basic" type="number" inputmode="numeric" value="40000"></div><div><label class="f">Mahine ke din</label><input id="mdays" type="number" inputmode="numeric" value="30"></div></div>`,calc:()=>{var d=+v('days'),b=+v('basic'),md=+v('mdays')||30;
  if(!d||!b)return '<div class="hint">Bachi leave aur basic+DA daalein.</div>';
  var perDay=b/md;
  var amt=perDay*d;
  return '<div class="lbl">Leave encashment (approx)</div><div class="big">'+RS(amt)+'</div>'
   +'<div class="rrow"><span>Per-day salary</span><b>'+RS(perDay)+'</b></div>'
   +'<div class="rrow"><span>Bachi leave</span><b>'+d+' din</b></div>'
   +'<div class="rrow"><span>Base (basic+DA)</span><b>'+RS(b)+'/mah</b></div>'
   +'<div class="hint">Sirf basic+DA par. Govt me tax-free, private me ek seema tak chhoot. Company niyam dekhein.</div>';}},
{id:'sgb',cat:'Nivesh',ic:'🥇',name:"Sovereign Gold Bond Calculator",desc:"Sovereign Gold Bond return",pop:0,fields:`<label class="f">Nivesh rakam (₹)</label><input id="a" type="number" inputmode="numeric" value="100000"><div class="row2"><div><label class="f">Gold price growth % (saalana)</label><input id="g" type="number" inputmode="decimal" value="8" step="0.1"></div><div><label class="f">Saal (8 tak)</label><input id="y" type="number" inputmode="numeric" value="8"></div></div>`,calc:()=>{var A=+v('a'),g=+v('g')/100,y=+v('y');
  if(!A||!y)return '<div class="hint">Nivesh aur saal daalein.</div>';
  var goldVal=A*Math.pow(1+g,y);
  var interest=A*0.025*y;
  var total=goldVal+interest;
  return '<div class="lbl">Anumaanit total ('+y+' saal)</div><div class="big">'+RS(total)+'</div>'
   +'<div class="rrow"><span>Gold value</span><b>'+RS(goldVal)+'</b></div>'
   +'<div class="rrow"><span>2.5% byaj (kul)</span><b>'+RS(interest)+'</b></div>'
   +'<div class="rrow"><span>Nivesh</span><b>'+RS(A)+'</b></div>'
   +'<div class="rrow"><span>Kul fayda</span><b>'+RS(total-A)+'</b></div>'
   +'<div class="hint">Gold growth anuman hai, guarantee nahi. Maturity par gain tax-free, par byaj taxable.</div>';}}
];


const grid=document.getElementById('grid');
/* ?q= se seedha search - WebSite schema ke SearchAction ke liye */
addEventListener('DOMContentLoaded',function(){try{var _q=new URLSearchParams(location.search).get('q');if(_q){var _e=document.getElementById('search');if(_e){_e.value=_q;if(typeof filterTools==='function')filterTools();var _t=document.getElementById('tools');if(_t)_t.scrollIntoView({behavior:'smooth'});}}}catch(e){}});
const cardHTML=t=>`<a class="tool" href="${PAGES[t.id]||('/?t='+t.id)}" data-id="${t.id}"><div class="ic">${t.ic}</div><h3>${t.name}</h3><p>${t.desc}</p><div class="tag">${t.cat}</div></a>`;
const drawGrid=l=>grid.innerHTML=l.length?l.map(cardHTML).join(''):'<div class="nores">Koi tool nahi mila. Doosra shabd try karein.</div>';
/* cards HTML me pehle se maujood hain - CLS 0.323 isi wajah se tha. Filter par hi dobara bante hain. */
const cc={};tools.forEach(t=>cc[t.cat]=(cc[t.cat]||0)+1);
const cats=['Sab',...Object.keys(cc)];
document.getElementById('cats').innerHTML=cats.map((c,i)=>`<button class="chip ${i===0?'on':''}" onclick="setCat('${c}',this)">${c}<b>${c==='Sab'?tools.length:cc[c]}</b></button>`).join('');
function setCat(c,el){document.querySelectorAll('.chip').forEach(x=>x.classList.remove('on'));el.classList.add('on');document.getElementById('search').value='';drawGrid(c==='Sab'?tools:tools.filter(t=>t.cat===c));}
function filterTools(){let q=v('search').toLowerCase().trim();document.querySelectorAll('.chip').forEach(x=>x.classList.remove('on'));document.querySelector('.chip').classList.add('on');drawGrid(!q?tools:tools.filter(t=>(t.name+' '+t.desc+' '+t.cat).toLowerCase().includes(q)));}
document.getElementById('popular').innerHTML='<small>Popular:</small>'+tools.filter(t=>t.pop).map(t=>`<a href="${PAGES[t.id]||('/?t='+t.id)}" data-id="${t.id}">${t.name.replace(/ Calculator| Generator/,'')}</a>`).join('');

const overlay=document.getElementById('overlay'),panel=document.getElementById('panel');let cur=null;
const GUIDES={s80c:'/section-80c-full-guide',deprec:'/depreciation-guide',zakat:'/zakat-guide',tdee:'/tdee-guide',macro:'/weight-loss-basics-guide',sci:'/scientific-calculator-guide',amort:'/loan-amortization-guide',bill:'/electricity-bill-guide',cgpa:'/gpa-percentage-guide',sip:'/sip-guide',stepupsip:'/sip-guide',lumpsum:'/sip-guide',sipgoal:'/sip-goal-guide',crorepati:'/sip-guide',sipdelay:'/sip-guide',emi:'/emi-guide',gst:'/gst-guide',ppf:'/ppf-guide',ssy:'/ppf-guide',bmi:'/bmi-guide',area:'/area-guide',epf:'/epf-guide',fd:'/fd-rd-guide',rd:'/fd-rd-guide',itax:'/income-tax-guide',taxcompare:'/tax-regime-guide',hra:'/income-tax-guide',nps:'/nps-guide',gratuity:'/gratuity-guide',ci:'/compound-interest-guide',si:'/compound-interest-guide',intraday:'/itr3-guide',possize:'/itr3-guide',brokerage:'/brokerage-guide',sltp:'/brokerage-guide',rr:'/brokerage-guide',homeaff:'/home-loan-guide',prepay:'/home-loan-guide',emi2:'/home-loan-guide',fire:'/fire-guide',emergency:'/emergency-fund-guide',budget:'/budget-50-30-20-guide',pomis:'/post-office-guide',kvp:'/post-office-guide',scss:'/post-office-guide',nsc:'/post-office-guide',tds:'/tds-guide',buyrent:'/buy-vs-rent-guide',roi:'/mutual-fund-vs-fd-guide',goallump:'/sip-guide',dti:'/credit-score-guide',ccpayoff:'/credit-score-guide',hourly:'/income-tax-guide'};
function gLink(id){return GUIDES[id]?`<a href="${GUIDES[id]}" style="display:block;text-align:center;margin-top:14px;font-size:.88rem;color:var(--brand);text-decoration:none;font-weight:600">📖 Iski poori guide padhein →</a>`:'';}
function openTool(id){cur=tools.find(t=>t.id===id);if(!cur)return;panel.innerHTML=`<div class="ptop"><h2>${cur.ic} ${cur.name}</h2><button class="x" onclick="closeTool()">✕</button></div>${cur.fields}${cur.custom?'':'<button class="btn" onclick="runCalc()">Hisaab lagao</button><div id="res" class="result"></div>'}${gLink(cur.id)}`;overlay.classList.add('on');document.body.style.overflow='hidden';const f={unit:renderUnit,area:renderArea,qr:genQR,word:wc,ntw:doNTW,temp:doTemp,speed:doSpeed,data:doData,roman:doRoman,readtime:doRead,currency:initCur};if(f[id])f[id]();}
function openPage(k){let p=PAGES[k];panel.innerHTML=`<div class="ptop"><h2>${p.t}</h2><button class="x" onclick="closeTool()">✕</button></div><div style="font-size:.95rem;color:#333">${p.h}</div>`;overlay.classList.add('on');document.body.style.overflow='hidden';}
function closeTool(){overlay.classList.remove('on');document.body.style.overflow='';swStop();cur=null;}
function runCalc(){let r=document.getElementById('res');r.innerHTML=cur.calc();r.classList.add('show');}
document.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a.tool,.pop a[data-id]');if(!a)return;
 if(e.metaKey||e.ctrlKey||e.shiftKey||e.button===1)return;
 var h=a.getAttribute('href')||'';if(h.indexOf('/?t=')===0){e.preventDefault();openTool(a.getAttribute('data-id'));}});
document.getElementById('navBtn').addEventListener('click',function(){var n=document.getElementById('hnav');var o=n.classList.toggle('open');this.setAttribute('aria-expanded',o);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTool();});

const U={len:{m:1,km:1000,cm:.01,mm:.001,mile:1609.34,ft:.3048,inch:.0254,yard:.9144},wt:{kg:1,g:.001,mg:1e-6,ton:1000,lb:.453592,oz:.0283495}};
function renderUnit(){let t=v('t'),o=Object.keys(U[t]);document.getElementById('from').innerHTML=o.map(x=>`<option>${x}</option>`).join('');document.getElementById('to').innerHTML=o.map((x,i)=>`<option ${i===1?'selected':''}>${x}</option>`).join('');doUnit();}
function doUnit(){let t=v('t'),val=+v('val'),o=document.getElementById('uout');if(!o)return;let r=val*U[t][v('from')]/U[t][v('to')];o.innerHTML=`<div class="lbl">${val} ${v('from')} =</div><div class="big">${NUM(+r.toFixed(4))} ${v('to')}</div>`;}
const AR={'sq ft':1,'sq m':10.7639,'gaj':9,'acre':43560,'hectare':107639,'bigha':27000};
function renderArea(){let o=Object.keys(AR);document.getElementById('from').innerHTML=o.map(x=>`<option>${x}</option>`).join('');document.getElementById('to').innerHTML=o.map((x,i)=>`<option ${i===5?'selected':''}>${x}</option>`).join('');doArea();}
function doArea(){let val=+v('val'),o=document.getElementById('areaout');if(!o)return;let r=val*AR[v('from')]/AR[v('to')];o.innerHTML=`<div class="lbl">${val} ${v('from')} =</div><div class="big">${NUM(+r.toFixed(4))}</div><div class="lbl">${v('to')}</div>`;}
function doTemp(){let val=+v('val'),f=v('from'),to=v('to'),o=document.getElementById('tout');if(!o)return;let c=f==='C'?val:f==='F'?(val-32)*5/9:val-273.15,r=to==='C'?c:to==='F'?c*9/5+32:c+273.15;o.innerHTML=`<div class="lbl">${val}°${f} =</div><div class="big">${NUM(+r.toFixed(2))}°${to}</div>`;}
const SP={kmph:1,mph:1.60934,'m/s':3.6};
function doSpeed(){let val=+v('val'),o=document.getElementById('spout');if(!o)return;let r=val*SP[v('from')]/SP[v('to')];o.innerHTML=`<div class="lbl">${val} ${v('from')} =</div><div class="big">${NUM(+r.toFixed(3))} ${v('to')}</div>`;}
const DA={KB:1,MB:1024,GB:1048576,TB:1073741824};
function doData(){let val=+v('val'),o=document.getElementById('dout');if(!o)return;let r=val*DA[v('from')]/DA[v('to')];o.innerHTML=`<div class="lbl">${val} ${v('from')} =</div><div class="big">${NUM(+r.toFixed(4))} ${v('to')}</div>`;}
function toRoman(n){if(n<1||n>3999)return '—';let m=[['M',1000],['CM',900],['D',500],['CD',400],['C',100],['XC',90],['L',50],['XL',40],['X',10],['IX',9],['V',5],['IV',4],['I',1]],r='';for(let[s,val]of m)while(n>=val){r+=s;n-=val;}return r;}
function doRoman(){let o=document.getElementById('romout');if(!o)return;o.innerHTML=`<div class="lbl">${+v('a')} =</div><div class="big">${toRoman(+v('a'))}</div>`;}
function numToWords(num){num=Math.floor(num);if(num===0)return 'Zero';if(num>999999999999)return 'Bahut bada';const a=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],b=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const two=n=>n<20?a[n]:b[Math.floor(n/10)]+(n%10?' '+a[n%10]:'');const three=n=>{let h=Math.floor(n/100),r=n%100;return (h?a[h]+' Hundred'+(r?' ':''):'')+(r?two(r):'');};let cr=Math.floor(num/1e7);num%=1e7;let lk=Math.floor(num/1e5);num%=1e5;let th=Math.floor(num/1e3);num%=1e3;let s='';if(cr)s+=three(cr)+' Crore ';if(lk)s+=three(lk)+' Lakh ';if(th)s+=three(th)+' Thousand ';if(num)s+=three(num);return s.trim();}
function doNTW(){let n=+v('a')||0,o=document.getElementById('ntwout');if(!o)return;o.innerHTML=`<div class="lbl">${RS(n)} =</div><div class="big" style="font-size:1.4rem">${numToWords(n)} Rupees</div><div class="hint">Cheque: "Rupees ${numToWords(n)} Only"</div>`;}
function wc(){let t=v('t')||'',o=document.getElementById('wout');if(!o)return;let w=t.trim()?t.trim().split(/\s+/).length:0;o.innerHTML=`<div class="lbl">Shabd</div><div class="big">${w}</div><div class="rrow"><span>Akshar (space)</span><b>${t.length}</b></div><div class="rrow"><span>Akshar (bina space)</span><b>${t.replace(/\s/g,'').length}</b></div><div class="rrow"><span>Lines</span><b>${t.trim()?t.split(/\n/).length:0}</b></div>`;}
function doRead(){let t=v('t')||'',o=document.getElementById('rdout');if(!o)return;let w=t.trim()?t.trim().split(/\s+/).length:0;let read=Math.max(1,Math.round(w/200)),speak=Math.max(1,Math.round(w/130));o.innerHTML=`<div class="lbl">Shabd: ${w}</div><div class="big" style="font-size:1.4rem">${read} min padhne</div><div class="rrow"><span>Bolne me (speech)</span><b>${speak} min</b></div>`;}
function doCase(m){let t=v('t')||'',o=document.getElementById('caseout'),r;if(m==='up')r=t.toUpperCase();else if(m==='low')r=t.toLowerCase();else if(m==='title')r=t.replace(/\w\S*/g,w=>w[0].toUpperCase()+w.slice(1).toLowerCase());else r=t.toLowerCase().replace(/(^\s*\w|[.!?]\s*\w)/g,c=>c.toUpperCase());o.classList.add('show');o.innerHTML=`<div class="lbl">Result</div><div style="margin:6px 0;word-break:break-word">${r||'—'}</div>`;}
function genPass(){let len=+v('len'),ch='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnpqrstuvwxyz23456789!@#$%&*',p='';for(let i=0;i<len;i++)p+=ch[Math.floor(Math.random()*ch.length)];let o=document.getElementById('pout');o.classList.add('show');o.innerHTML=`<div class="lbl">Password</div><div class="big" style="font-size:1.3rem;word-break:break-all">${p}</div><button class="btn" onclick="navigator.clipboard.writeText('${p}');this.textContent='Copy ✓'">Copy</button>`;}
let qrObj=null;function genQR(){let o=document.getElementById('qrout');if(!o)return;o.innerHTML='';try{qrObj=new QRCode(o,{text:v('t')||' ',width:200,height:200,colorDark:'#0F1720',colorLight:'#fff'});}catch(e){}}
function doRandom(){let mn=+v('mn'),mx=+v('mx'),o=document.getElementById('rout');o.classList.add('show');o.innerHTML=`<div class="lbl">Random (${mn}-${mx})</div><div class="big">${Math.floor(Math.random()*(mx-mn+1))+mn}</div>`;}
function doDice(){let o=document.getElementById('rout');o.classList.add('show');o.innerHTML=`<div class="lbl">Dice</div><div class="big">🎲 ${Math.floor(Math.random()*6)+1}</div>`;}
function doCoin(){let o=document.getElementById('rout');o.classList.add('show');o.innerHTML=`<div class="lbl">Sikka</div><div class="big">${Math.random()<.5?'🪙 Heads':'🪙 Tails'}</div>`;}
let swT=0,swInt=null;
function swFmt(ms){return String(Math.floor(ms/60000)).padStart(2,'0')+':'+String(Math.floor(ms%60000/1000)).padStart(2,'0')+'.'+Math.floor(ms%1000/100);}
function swStart(){if(swInt)return;let start=Date.now()-swT;swInt=setInterval(()=>{swT=Date.now()-start;let e=document.getElementById('swd');if(e)e.textContent=swFmt(swT);},100);}
function swStop(){clearInterval(swInt);swInt=null;}
function swReset(){swStop();swT=0;let e=document.getElementById('swd');if(e)e.textContent='00:00.0';}
function doLove(){let a=v('a').trim(),b=v('b').trim(),o=document.getElementById('lout');if(!a||!b){o.classList.add('show');o.innerHTML='<div class="hint">Dono naam likhiye.</div>';return;}let s=0;for(let c of (a+b).toLowerCase())s+=c.charCodeAt(0);o.classList.add('show');o.innerHTML=`<div class="lbl">${a} ❤️ ${b}</div><div class="big">${s%101}%</div><div class="hint">Sirf mazaak ke liye 😊</div>`;}

var CUR=["USD","INR","EUR","GBP","AED","SAR","AUD","CAD","JPY","CNY","SGD","NPR","BDT"];
function initCur(){var f=document.getElementById('from'),t=document.getElementById('to');if(!f||!t)return;f.innerHTML=CUR.map(function(c){return '<option'+(c==='USD'?' selected':'')+'>'+c+'</option>'}).join('');t.innerHTML=CUR.map(function(c){return '<option'+(c==='INR'?' selected':'')+'>'+c+'</option>'}).join('');}
async function doCurrency(){var o=document.getElementById('cxout');o.classList.add('show');o.innerHTML='<div class="lbl">Loading...</div>';try{var from=v('from'),to=v('to'),amt=+v('amt');var r=await fetch('https://open.er-api.com/v6/latest/'+from);var d=await r.json();var rate=d.rates[to];if(!rate)throw 0;o.innerHTML='<div class="lbl">'+amt+' '+from+' =</div><div class="big">'+(amt*rate).toLocaleString('en-IN',{maximumFractionDigits:2})+' '+to+'</div><div class="rrow"><span>1 '+from+'</span><b>'+rate.toFixed(4)+' '+to+'</b></div><div class="hint">Live rate. Sirf jaankari ke liye.</div>';}catch(e){o.innerHTML='<div class="hint">Rate nahi mila. Internet check karein.</div>';}}
async function doWeather(){var o=document.getElementById('wxout');o.classList.add('show');o.innerHTML='<div class="lbl">Loading...</div>';try{var city=v('city');var g=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(city)+'&count=1');var gd=await g.json();if(!gd.results||!gd.results.length){o.innerHTML='<div class="hint">Sheher nahi mila. Sahi naam likhein.</div>';return;}var la=gd.results[0].latitude,lo=gd.results[0].longitude,nm=gd.results[0].name;var w=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+la+'&longitude='+lo+'&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code&daily=temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=2');var wd=await w.json();var cw=wd.current,dl=wd.daily;o.innerHTML='<div class="lbl">'+nm+' — abhi</div><div class="big">'+Math.round(cw.temperature_2m)+'°C</div><div class="rrow"><span>Humidity</span><b>'+cw.relative_humidity_2m+'%</b></div><div class="rrow"><span>Hawa</span><b>'+cw.wind_speed_10m+' km/h</b></div><div class="rrow"><span>Aaj</span><b>'+Math.round(dl.temperature_2m_min[0])+'° / '+Math.round(dl.temperature_2m_max[0])+'°</b></div><div class="rrow"><span>Kal</span><b>'+Math.round(dl.temperature_2m_min[1])+'° / '+Math.round(dl.temperature_2m_max[1])+'°</b></div>';}catch(e){o.innerHTML='<div class="hint">Mausam nahi mila. Internet check karein.</div>';}}
async function doDict(){var o=document.getElementById('dxout');o.classList.add('show');o.innerHTML='<div class="lbl">Loading...</div>';try{var word=v('word').trim();var r=await fetch('https://api.dictionaryapi.dev/api/v2/entries/en/'+encodeURIComponent(word));if(!r.ok)throw 0;var d=await r.json();var e=d[0],ph=e.phonetic||'',ms=e.meanings.slice(0,3).map(function(m){return '<div class="rrow"><span>'+m.partOfSpeech+'</span><b style="max-width:60%;text-align:right">'+m.definitions[0].definition+'</b></div>';}).join('');o.innerHTML='<div class="lbl">'+e.word+' '+ph+'</div>'+ms;}catch(e){o.innerHTML='<div class="hint">Word nahi mila. Spelling check karein (English word).</div>';}}

(function(){try{var _t=new URLSearchParams(location.search).get('t');if(_t&&tools.some(function(x){return x.id===_t}))openTool(_t);}catch(e){}})();
